import { existsSync, statSync } from "node:fs";
import fastify, { type FastifyInstance } from "fastify";
import fastifyStatic from "@fastify/static";
import { config, ensureLogFilesExist } from "./config";
import { RotatingNdjsonTail } from "./ingest/rotatingNdjsonTail";
import { TailFile } from "./ingest/tailFile";
import { normalizeMetricSampleLine, normalizeStreamsLine, normalizeTimelineLine, normalizeTopologyLine, type NormalizedInterfaceInput, type NormalizedMetricInput } from "./normalizer";
import { applyProjectedLifecycleEvent, loadProjectedStreamState, materializeProjectedStreamStates, type JsonRecord } from "./history/stream_state_query";
import { queryProjectedTopologyAt } from "./history/topology_state_query";
import { queryEventsHistory } from "./history/events_query";
import { normalizeEventLine } from "./events";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";
import { MaintenanceSettings } from "./maintenanceSettings";
import { AlertsSettings } from "./alertsSettings";
import { ProtocolMapSettings } from "./protocolMapSettings";
import { CaptureHealthStore } from "./captureHealth";
import { CapturePolicySettings } from "./capturePolicySettings";
import { CaptureSettings } from "./captureSettings";
import { SetupSettings } from "./setupSettings";
import { SetupProfiles } from "./setupProfiles";

type RunningTail = { start(): void; stop(): void };

async function main() {
  ensureLogFilesExist();
  diagnostic(`startup source=projected cwd=${process.cwd()} root=${config.rootDir} logDir=${config.logDir} port=${config.port}`);
  diagnosticInputs();

  const app = fastify({ logger: config.httpAccessLog });
  const alertsSettings = config.stmConfigFile ? new AlertsSettings(config.stmConfigFile) : undefined;
  const protocolMapSettings = config.stmConfigFile ? new ProtocolMapSettings(config.stmConfigFile) : undefined;
  const capturePolicySettings = new CapturePolicySettings(config.capturePolicyFile);
  const captureSettings = config.stmConfigFile ? new CaptureSettings(config.stmConfigFile, () => capturePolicySettings.get()) : undefined;
  const setupSettings = captureSettings && protocolMapSettings && alertsSettings ? new SetupSettings(capturePolicySettings, captureSettings, protocolMapSettings, alertsSettings) : undefined;
  const setupProfiles = new SetupProfiles(config.setupProfilesFile);
  const maintenanceSettings = await MaintenanceSettings.load({
    definitionFile: config.maintenanceSettingsFile,
    runtimeFile: config.runtimeSettingsFile,
    defaults: { lostRetentionSec: config.lostRetentionSec, historyWindowSec: config.historyWindowSec, staleAfterSec: config.staleAfterSec, diagnosticLog: config.diagnosticLog, dashboardLayoutEditMode: config.dashboardLayoutEditMode, streamsErrorCountMode: config.streamsErrorCountMode, streamsRecentAlertRetentionMin: config.streamsRecentAlertRetentionMin, streamsAlertDisplay: config.streamsAlertDisplay, historicalSparklines: config.historicalSparklines, streamsSparklineSamples: config.streamsSparklineSamples, tooltipDelayMs: config.tooltipDelayMs }
  });
  Object.assign(config, maintenanceSettings.get().values);
  const store = new StreamStore(config.historyWindowSec, config.timelineWindowSec, config.lostRetentionSec, config.maxEvents, config.maxTimelineRows, config.topologyStaleRetentionSec, config.topologyMaxStaleEdges, config.topologyMaxDetailFlowsPerRelation, config.streamsErrorCountMode, config.streamsSparklineSamples);
  const captureHealth = new CaptureHealthStore(config.captureHealthStaleAfterSec);
  const now = Date.now() / 1000;
  const initialEvents = await queryEventsHistory({ from: now - 24 * 3600, to: now, limit: config.maxEvents });
  for (const event of initialEvents.reverse()) store.addEvent(event);

  const initialTopology = await queryProjectedTopologyAt({ checkpointDir: config.topologyCheckpointDir, updatesDir: config.topologyUpdatesDir, time: now });
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic(`initial state events=${store.listEvents({ limit: config.maxEvents }).length} topology=${initialTopology ? "loaded" : "missing"}`);

  const sockets = new SocketServer(app.server, store, captureHealth, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  await registerRoutes(app, store, maintenanceSettings, alertsSettings, protocolMapSettings, capturePolicySettings, captureSettings, setupSettings, setupProfiles, captureHealth, (values) => {
    Object.assign(config, values);
    store.updateRuntimeConfig(values);
    sockets.broadcastConfig(values);
  });
  if (existsSync(config.externalPagesDir)) {
    await app.register(fastifyStatic, { root: config.externalPagesDir, prefix: "/external-pages/", decorateReply: false });
  }
  if (existsSync(config.localesDir)) {
    await app.register(fastifyStatic, { root: config.localesDir, prefix: "/locales/", decorateReply: false, setHeaders: (response) => response.setHeader("Cache-Control", "no-store") });
  }
  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, { root: config.clientDist, prefix: "/" });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws" || request.raw.url?.startsWith("/external-pages/") || request.raw.url?.startsWith("/locales/")) return reply.code(404).send({ error: "not found" });
      return reply.sendFile("index.html");
    });
  }

  sockets.start();
  const { tails, flushMetrics } = await createProjectedTails(app, store, sockets, captureHealth);
  tails.forEach((tail) => tail.start());
  const close = async () => { flushMetrics(); tails.forEach((tail) => tail.stop()); await app.close(); };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());
  await app.listen({ host: config.host, port: config.port });
}

async function createProjectedTails(app: FastifyInstance, store: StreamStore, sockets: SocketServer, captureHealth: CaptureHealthStore): Promise<{ tails: RunningTail[]; flushMetrics: () => void }> {
  const state = await loadProjectedStreamState(config.streamStateDir, Number.POSITIVE_INFINITY);
  const applyStreams = (time: number) => store.applyStreamSnapshot(materializeProjectedStreamStates(state.streams, time), time);
  if (state.hasRecords) applyStreams(Date.now() / 1000);

  const streams = new RotatingNdjsonTail({ root: `${config.streamStateDir}/delta`, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    recordId: sourceRecordId,
    initialSkipRecordIds: state.latestDeltaRecordIds,
    onLine: (line) => { try { const delta = parseRecord(line); const time = Number(delta?.time ?? 0); if (!delta || !Number.isFinite(time) || time < state.checkpointTime) return; applyProjectedLifecycleEvent(state.streams, delta.event); applyStreams(time); } catch (error) { app.log.warn({ error }, "failed to parse projected stream delta"); } },
    onError: (error) => app.log.warn({ error }, "failed to tail projected stream deltas") });
  const metricBatch = createMetricSampleBatcher(store, app);
  const metrics = new RotatingNdjsonTail({ root: config.metricsSamples1sDir, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    onLine: metricBatch.push, onError: (error) => app.log.warn({ error }, "failed to tail projected metrics") });
  const events = new RotatingNdjsonTail({ root: config.eventJournalDir, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    onLine: (line) => ingestEvent(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail event journal") });
  const availability = new RotatingNdjsonTail({ root: config.timelineAvailabilityDir, extension: ".ndjson", pollMs: config.pollMs, startAtEnd: true,
    onLine: (line) => { if (parseRecord(line)?.record_type === "timeline_availability") sockets.broadcastLiveHeartbeat(); },
    onError: (error) => app.log.warn({ error }, "failed to tail timeline availability") });

  const timeline = new TailFile({ path: config.timelineLiveFile, pollMs: config.pollMs,
    onLine: (line) => ingestTimeline(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected timeline live") });
  const topology = new TailFile({ path: config.topologyLiveFile, pollMs: config.pollMs, startAtLatestLine: true,
    onLine: (line) => ingestTopology(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected topology live") });
  const health = new TailFile({ path: config.captureHealthLiveFile, pollMs: config.pollMs, startAtLatestLine: true,
    onLine: (line) => { try { captureHealth.update(JSON.parse(line)); } catch (error) { app.log.warn({ error }, "failed to parse capture health snapshot"); } }, onError: (error) => app.log.warn({ error }, "failed to tail capture health") });
  const healthEvents = new TailFile({ path: config.captureHealthEventsFile, pollMs: config.pollMs,
    onLine: (line) => ingestEvent(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail capture health events") });
  return { tails: [streams, metrics, events, availability, timeline, topology, health, healthEvents], flushMetrics: metricBatch.flush };
}

function createMetricSampleBatcher(store: StreamStore, app: FastifyInstance) {
  const interfaces: NormalizedInterfaceInput[] = [];
  const metrics: NormalizedMetricInput[] = [];
  let timer: NodeJS.Timeout | undefined;

  const flush = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
    const interfaceBatch = interfaces.splice(0, interfaces.length);
    const metricBatch = metrics.splice(0, metrics.length);
    if (interfaceBatch.length > 0) store.upsertInterfaces(interfaceBatch);
    if (metricBatch.length > 0) store.addMetrics(metricBatch);
  };

  return {
    push: (line: string) => {
      try {
        const sample = normalizeMetricSampleLine(line);
        if (!sample) return;
        if (sample.interface) interfaces.push(sample.interface);
        if (sample.metric) metrics.push(sample.metric);
        if (!timer) timer = setTimeout(flush, 50);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metric sample");
      }
    },
    flush
  };
}
function ingestEvent(store: StreamStore, line: string, app: FastifyInstance) {
  try { const event = normalizeEventLine(line); if (event) store.addEvent(event); }
  catch (error) { app.log.warn({ error }, "failed to parse event line"); }
}
function ingestTimeline(store: StreamStore, line: string, app: FastifyInstance) {
  try { const item = normalizeTimelineLine(line); if (item) store.addTimelineEvent(item); }
  catch (error) { app.log.warn({ error }, "failed to parse timeline line"); }
}
function ingestTopology(store: StreamStore, line: string, app: FastifyInstance) {
  try { const snapshot = normalizeTopologyLine(line); if (snapshot) store.applyTopologySnapshot(snapshot); }
  catch (error) { app.log.warn({ error }, "failed to parse topology line"); }
}
function parseRecord(line: string): JsonRecord | undefined {
  try { const value = JSON.parse(line) as unknown; return value && typeof value === "object" && !Array.isArray(value) ? value as JsonRecord : undefined; } catch { return undefined; }
}
function sourceRecordId(line: string) { const delta = parseRecord(line); return typeof delta?.source_record_id === "string" ? delta.source_record_id : undefined; }
function diagnosticInputs() {
  const inputs = { streams: config.streamStateDir, metrics: config.metricsSamples1sDir, events: config.eventJournalDir, timeline: config.timelineLiveFile, topology: config.topologyLiveFile, captureHealth: config.captureHealthLiveFile };
  for (const [label, file] of Object.entries(inputs)) {
    try { const info = statSync(file); diagnostic(`input ${label} path=${file} size=${info.size} mtime=${info.mtime.toISOString()}`); }
    catch (error) { diagnostic(`input ${label} path=${file} error=${String(error)}`); }
  }
}
function diagnostic(message: string) { if (config.diagnosticLog) console.error("[STM_DIAG] " + message); }


main().catch((error) => { console.error(error); process.exit(1); });
import { promises as fs } from "node:fs";

const READ_CHUNK_BYTES = 1024 * 1024;

export type TailFileOptions = {
  path: string;
  pollMs: number;
  /** On the initial read, consume only the last completed NDJSON line. */
  startAtLatestLine?: boolean;
  onLine: (line: string) => void;
  onChunk?: (info: {
    start: number;
    end: number;
    bytes: number;
    lines: number;
    observedAt: number;
    processedAt: number;
    processingMs: number;
  }) => void;
  onError?: (error: unknown) => void;
};

export class TailFile {
  private offset = 0;
  private inode?: number;
  private dev?: number;
  private buffer = "";
  private timer?: NodeJS.Timeout;
  private reading = false;

  constructor(private readonly options: TailFileOptions) {}

  start() {
    this.timer = setInterval(() => void this.tick(), this.options.pollMs);
    void this.tick();
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
  }

  private async tick() {
    if (this.reading) return;
    this.reading = true;
    try {
      const stat = await fs.stat(this.options.path);
      const rotated = this.inode !== undefined && (stat.ino !== this.inode || stat.dev !== this.dev);
      const truncated = stat.size < this.offset;

      if (rotated || truncated) {
        this.offset = 0;
        this.buffer = "";
      }

      const initial = this.inode === undefined;
      this.inode = stat.ino;
      this.dev = stat.dev;

      if(initial && this.options.startAtLatestLine) {
        const line = await this.readLatestCompleteLine(stat.size);
        this.offset = stat.size;
        this.buffer = "";
        if(line) this.options.onLine(line);
        return;
      }

      if (stat.size > this.offset) {
        const start = this.offset;
        const end = stat.size;
        const observedAt = Date.now();
