        this.cursorPath = latestFile;
        this.cursorOffset = (await fs.stat(latestFile)).size;
        return;
      }

      let index = this.cursorPath ? files.indexOf(this.cursorPath) : (this.options.startAtLatestFile ? files.length - 1 : 0);
      if (index < 0) index = files.findIndex((file) => !this.cursorPath || file > this.cursorPath);
      if (index < 0) return;

      for (; index < files.length; index += 1) {
        const file = files[index];
        if (file !== this.cursorPath) {
          this.cursorPath = file;
          this.cursorOffset = 0;
        }
        const hasPartialLine = await this.readAvailable(file);
        if (hasPartialLine || index === files.length - 1) break;
      }
    } catch (error) {
      this.options.onError?.(error);
    } finally {
      this.reading = false;
    }
  }

  private async listFiles() {
    const files: string[] = [];
    const walk = async (directory: string): Promise<void> => {
      let entries;
      try {
        entries = await fs.readdir(directory, { withFileTypes: true });
      } catch (error: any) {
        if (error?.code === "ENOENT") return;
        throw error;
      }
      for (const entry of entries) {
        const candidate = path.join(directory, entry.name);
        if (entry.isDirectory()) await walk(candidate);
        else if (entry.isFile() && entry.name.endsWith(this.options.extension)) files.push(candidate);
      }
    };
    await walk(this.options.root);
    return files.sort();
  }

  private async readAvailable(file: string) {
    const stat = await fs.stat(file);
    if (stat.size < this.cursorOffset) this.cursorOffset = 0;
    if (stat.size === this.cursorOffset) return false;

    const handle = await fs.open(file, "r");
    try {
      let position = this.cursorOffset;
      let pending = Buffer.alloc(0);
      while (position < stat.size) {
        const length = Math.min(READ_CHUNK_BYTES, stat.size - position);
        const chunk = Buffer.allocUnsafe(length);
        const { bytesRead } = await handle.read(chunk, 0, length, position);
        if (bytesRead <= 0) break;
        position += bytesRead;
        pending = Buffer.concat([pending, chunk.subarray(0, bytesRead)]);

        let newline = pending.indexOf(0x0a);
        while (newline >= 0) {
          const line = pending.subarray(0, newline).toString("utf8").replace(/\r$/, "").trim();
          this.cursorOffset += newline + 1;
          pending = pending.subarray(newline + 1);
          if (line) this.consumeLine(line, file);
          newline = pending.indexOf(0x0a);
        }
      }
      return pending.length > 0;
    } finally {
      await handle.close();
    }
  }

  private consumeLine(line: string, file: string) {
    const recordId = this.options.recordId?.(line) ?? extractRecordId(line);
    if (recordId) {
      if (this.initialSkipRecordIds?.has(recordId)) return;
      if (this.recentRecordIds.has(recordId)) return;
      this.recentRecordIds.add(recordId);
      this.recentRecordOrder.push(recordId);
      const limit = this.options.maxRecentRecordIds ?? 10_000;
      while (this.recentRecordOrder.length > limit) {
        const oldest = this.recentRecordOrder.shift();
        if (oldest) this.recentRecordIds.delete(oldest);
      }
    }
    this.options.onLine(line, file);
  }
}

function extractRecordId(line: string) {
  try {
    const record = JSON.parse(line) as { record_id?: unknown };
    return typeof record.record_id === "string" ? record.record_id : undefined;
  } catch {
    return undefined;
  }
}
