      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        const metrics = await queryInterfaceMetricsHistory({ key, from: from!, to: to! });
        if (!metrics) return reply.code(404).send({ error: "interface history not available" });
        return metrics;
      }
      const metrics = store.getInterfaceMetricsByKey(key, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Querystring: { time?: string; overviewEventFrom?: string; overviewEventTo?: string; includeSparkline?: string } }>("/api/streams", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    const overviewEventFrom = request.query.overviewEventFrom ? Number(request.query.overviewEventFrom) : undefined;
    const overviewEventTo = request.query.overviewEventTo ? Number(request.query.overviewEventTo) : undefined;
    const overviewEventsRequested = request.query.overviewEventFrom !== undefined || request.query.overviewEventTo !== undefined;
    const includeSparkline = request.query.includeSparkline === "1";
    if (overviewEventsRequested && (!Number.isFinite(time) || !Number.isFinite(overviewEventFrom) || !Number.isFinite(overviewEventTo) || overviewEventTo! < overviewEventFrom! || Math.abs(overviewEventTo! - time!) > 0.001 || overviewEventTo! - overviewEventFrom! > 24 * 3600)) {
      return reply.code(400).send({ error: "invalid overview event range" });
    }
    if (Number.isFinite(time)) {
      let snapshot = await queryProjectedStreamsAt(config.streamStateDir, time!);
      if (!snapshot) return reply.code(404).send({ error: "streams snapshot not available" });
      const metricsSnapshot = await queryMetricsSnapshotAt(time!);
      if (metricsSnapshot) snapshot = enrichProjectedStreamSnapshot(snapshot, metricsSnapshot.interfaces, metricsSnapshot.metrics, config.streamsErrorCountMode);
      if (includeSparkline) {
        const sparklines = await queryHistoricalSparklinesAt({ time: time!, samples: config.streamsSparklineSamples, streams: snapshot.streams, interfaces: snapshot.interfaces });
        snapshot = {
          ...snapshot,
          streams: snapshot.streams.map((stream) => ({
