          }))
        };
      }
      if (overviewEventsRequested) {
        const [gaps, latestObservedAt] = await Promise.all([
          queryTimelineDataGaps({ from: overviewEventFrom!, to: overviewEventTo! }),
          queryLatestTimelineAvailabilityAtOrBefore(overviewEventTo!)
        ]);
        const eventsAvailable = latestObservedAt !== undefined
          && latestObservedAt >= overviewEventTo! - AVAILABILITY_MAX_INTERVAL_SEC
          && gaps.length === 0;
        const counts = eventsAvailable
          ? await queryOverviewEventCounts({ from: overviewEventFrom!, to: overviewEventTo! })
          : { streams: new Map<string, number>(), flows: new Map<string, number>(), streamOnly: new Map<string, number>() };
