  });

  app.get<{ Querystring: { relation?: string; state?: "active" | "all"; limit?: string } }>("/api/topology/flows", async (request, reply) => {
    const relation = request.query.relation;
    if (!relation) return reply.code(400).send({ error: "relation is required" });
    const requestedLimit = Number(request.query.limit ?? 50);
    const limit = Number.isFinite(requestedLimit) ? Math.min(Math.max(1, Math.floor(requestedLimit)), 100) : 50;
    const flows = store.getTopologyRelationFlows(relation, request.query.state === "all" ? "all" : "active", limit);
    if (!flows) return reply.code(404).send({ error: "topology relation not available" });
    return flows;
  });

  app.get<{ Querystring: { from?: string; to?: string; includeFlows?: string } }>("/api/timeline", async (request): Promise<TimelineViewResponse> => {
    const from = request.query.from ? Number(request.query.from) : undefined;
