		std::filesystem::path event_journal_dir;
		std::filesystem::path metrics_journal_dir;
		std::filesystem::path output_dir;
		std::filesystem::path state_file;
		std::uint64_t timeline_rotate_size_bytes{2ULL * 1024ULL * 1024ULL};
		std::size_t timeline_rotate_files{3};
		std::chrono::milliseconds poll_interval{1000};
		// Coalesce full topology materialization. Lifecycle events remain
		// individually recorded in the event and topology-event journals.
		std::chrono::milliseconds topology_publish_interval{1000};
		std::uint64_t part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t retention_hours{72U};
		std::uint32_t topology_checkpoint_interval_sec{60U};
	};

	explicit stm_projector(config cfg);
	int run_once();
	int run_follow();

private:
	config m_cfg;
	journal_reader m_events;
	journal_reader m_metrics;
	journal_reader::cursor m_event_cursor;
	journal_reader::cursor m_metrics_cursor;
	std::unique_ptr<writer> m_timeline_writer;
	std::unique_ptr<timeline_sink> m_timeline_sink;
	std::unique_ptr<timeline_projector> m_timeline_projector;
	std::unique_ptr<time_rotating_writer> m_timeline_availability_writer;
	std::unique_ptr<metric_sample_projector> m_metrics_projector;
