	std::unique_ptr<topology_state_projector> m_topology_state;
	std::unique_ptr<writer> m_topology_writer;
	std::unique_ptr<time_rotating_writer> m_topology_events_writer;
	json::array_t m_current_metrics;
	json::array_t m_current_interfaces;
	json m_active_alerts = json::object();
	std::string m_last_event_record_id;
	std::string m_last_metrics_record_id;
	bool m_topology_dirty{false};
	double m_pending_topology_time{0.0};
	json m_pending_topology_source = json::object();
	std::chrono::steady_clock::time_point m_last_topology_publish{};

	void load_state();
	void save_state() const;
