		if(relative == cursor.path) {
			std::error_code ec{};
			const auto file_size = std::filesystem::file_size(path, ec);
			const auto current_start = first_record(path);
			if(!ec && file_size < cursor.offset) {
				reset_replaced_cursor(cursor, relative, file_size, "truncated");
				cursor.file_start_record_id = current_start.record_id;
			}
			else if(cursor.file_start_record_id.empty()) {
				if(!cursor.record_id.empty() && !current_start.capture_id.empty() &&
				   !record_matches_capture(cursor.record_id, current_start.capture_id)) {
					reset_replaced_cursor(cursor, relative, ec ? 0 : file_size, "capture-changed");
					cursor.file_start_record_id = current_start.record_id;
				}
				else {
					cursor.file_start_record_id = current_start.record_id;
				}
			}
			else {
				if(!current_start.record_id.empty() &&
				   current_start.record_id != cursor.file_start_record_id) {
					reset_replaced_cursor(cursor, relative, ec ? 0 : file_size, "start-record-changed");
					cursor.file_start_record_id = current_start.record_id;
				}
			}
		}

		std::ifstream input(path);
		if(!input) {
			continue;
		}

		std::uint64_t offset = 0;
		std::string line;
		while(std::getline(input, line)) {
			const std::uint64_t next_offset = offset + static_cast<std::uint64_t>(line.size()) + 1U;
			if(relative == cursor.path && next_offset <= cursor.offset) {
				offset = next_offset;
				continue;
			}
			offset = next_offset;
			if(line.empty()) {
				continue;
			}

			json record;
			try {
				record = json::parse(line);
			}
			catch(const json::parse_error &) {
				// A writer can leave a partial final line while it is appending. Keep it for the next pass.
				break;
			}
			if(!record.is_object()) {
				advance_cursor(cursor, relative, next_offset, {});
				out.advanced = true;
				continue;
			}
			if(handler(record) != 0) {
				return out;
			}
			advance_cursor(cursor, relative, next_offset,
			               record.value("record_id", std::string{}));
			++out.records;
			out.advanced = true;
		}
	}
	return out;
}

json journal_reader::cursor_json(const cursor &cursor) {
	return json{
		{"path", cursor.path},
		{"offset", cursor.offset},
		{"record_id", cursor.record_id},
		{"file_start_record_id", cursor.file_start_record_id},
	};
}

journal_reader::cursor journal_reader::cursor_from_json(const json &value) {
	if(!value.is_object()) {
		return {};
	}
	return cursor{
		.path = value.value("path", std::string{}),
		.offset = value.value("offset", std::uint64_t{0}),
		.record_id = value.value("record_id", std::string{}),
		.file_start_record_id = value.value("file_start_record_id", std::string{}),
	};
}

std::vector<std::filesystem::path> journal_reader::list_files() const {
	std::vector<std::filesystem::path> files;
	std::error_code ec{};
	if(!std::filesystem::exists(m_root, ec)) {
		return files;
	}
	for(const auto &entry : std::filesystem::recursive_directory_iterator(m_root, ec)) {
		if(ec) {
			break;
		}
		if(!entry.is_regular_file()) {
			continue;
		}
		if(entry.path().extension() != ".ndjson") {
			continue;
		}
		files.push_back(entry.path());
	}
	std::sort(files.begin(), files.end());
	return files;
}
