event_journal_sink::event_journal_sink(time_rotating_writer &writer, std::string capture_id, double started_at, std::string protocol_map_revision)
	: m_writer(writer)
	, m_capture_id(std::move(capture_id))
	, m_started_at(started_at)
	, m_protocol_map_revision(std::move(protocol_map_revision)) {
	json record{
		{"schema_version", 2},
		{"record_type", "event"},
		{"capture_id", m_capture_id},
		{"run_id", m_capture_id},
		{"producer", {{"component", "stm"}, {"run_id", m_capture_id}, {"started_at", m_started_at}, {"protocol_map_revision", m_protocol_map_revision}}},
		{"record_id", m_capture_id + ":event:" + std::to_string(m_seq++)},
		{"seq", 0},
		{"time", m_started_at},
		{"event_time", m_started_at},
		{"emitted_at", m_started_at},
		{"type", "run_started"},
		{"source", json::object()},
	};
	m_writer.dump_at(m_started_at, record);
}

//--------------------------------------------------------------------------------
int event_journal_sink::handle_event(const event_record &e) {
	const auto emitted_now = std::chrono::duration<double>(
		std::chrono::system_clock::now().time_since_epoch()).count();
	const auto seq = m_seq++;
	json record{
		{"schema_version", 2},
		{"record_type", "event"},
		{"capture_id", m_capture_id},
		{"run_id", m_capture_id},
		{"producer", {{"component", "stm"}, {"run_id", m_capture_id}, {"started_at", m_started_at}, {"protocol_map_revision", m_protocol_map_revision}}},
		{"record_id", m_capture_id + ":event:" + std::to_string(seq)},
		{"seq", seq},
		{"time", e.time_epoch},
		{"event_time", e.time_epoch},
		{"emitted_at", emitted_now},
		{"type", e.type},
	};
	if(e.source.is_null() == false && e.source.empty() == false) {
		record["source"] = e.source;
	}
	if(e.detail.is_null() == false && e.detail.empty() == false) {
		record["detail"] = e.detail;
	}
	return m_writer.dump_at(e.time_epoch, record);
}

