bool lifecycle_type(const std::string &type, const char *subject) {
	return type == std::string(subject) + "_detected" ||
	       type == std::string(subject) + "_recovered" ||
	       type == std::string(subject) + "_lost";
}

bool is_detect(const std::string &type) {
	return type.ends_with("_detected") || type.ends_with("_recovered");
}

bool flow_state_update_type(const std::string &type) {
	return type == "flow_role_updated";
}

bool alert_state_update_type(const std::string &type) {
	return type == "alert_detected" || type == "alert_recovered" || type == "alert_data_unavailable" || type == "alert_data_available";
}

bool reclassification_type(const std::string &type) {
	return type == "transport_reclassified";
}

void apply_reclassification(json &streams, const json &detail, double time) {
	const auto from = detail.value("from", json::object());
	if(!from.is_object()) return;
	const auto flows = from.value("flows", json::array());
	if(flows.is_array()) {
		for(const auto &entry : flows) {
			if(!entry.is_object()) continue;
			const auto source = entry.value("source", json::object());
			const auto stream_key = source.value("stream_key", std::string{});
			const auto flow_key = source.value("flow_key", std::string{});
			if(stream_key.empty() || flow_key.empty()) continue;
			auto stream_it = streams.find(stream_key);
			if(stream_it == streams.end() || !stream_it->is_object()) continue;
			auto &flow = (*stream_it)["flows"][flow_key];
			if(!flow.is_object()) continue;
			flow["active"] = false;
			flow["last_seen"] = time;
		}
	}
	const auto removed_streams = from.value("streams", json::array());
	if(removed_streams.is_array()) {
		for(const auto &entry : removed_streams) {
			if(!entry.is_object()) continue;
			const auto source = entry.value("source", json::object());
			const auto stream_key = source.value("stream_key", std::string{});
			if(stream_key.empty()) continue;
			auto stream_it = streams.find(stream_key);
			if(stream_it == streams.end() || !stream_it->is_object()) continue;
			auto &stream = *stream_it;
			stream["active"] = false;
			stream["last_seen"] = time;
			if(stream.contains("flows") && stream["flows"].is_object()) {
				for(auto &[_, flow] : stream["flows"].items()) {
					if(!flow.is_object()) continue;
					flow["active"] = false;
					flow["last_seen"] = time;
				}
			}
		}
	}
}

void update_alert_state(json &subject, const json &source, const json &detail, const std::string &type, double time) {
	json alert = source;
	if(detail.is_object()) {
		for(const auto &[key, value] : detail.items()) alert[key] = value;
	}
	const auto key = alert.value("state_key", alert.value("alert_id", std::string{}));
	if(key.empty()) return;
	alert["state_key"] = key;
	auto &active = subject["alerts"];
	if(!active.is_object()) active = json::object();
	auto &recent = subject["recent_alerts"];
	if(!recent.is_object()) recent = json::object();
	if(type == "alert_detected" || type == "alert_data_unavailable") {
		if(active.contains(key) && active[key].is_object() && active[key].contains("started_at")) alert["started_at"] = active[key]["started_at"];
		else alert["started_at"] = time;
		alert["state"] = "active";
		alert["updated_at"] = time;
		active[key] = std::move(alert);
		recent.erase(key);
	}
	else {
		if(active.contains(key) && active[key].is_object() && active[key].contains("started_at")) alert["started_at"] = active[key]["started_at"];
		else alert["started_at"] = time;
		alert["state"] = "recovered";
		alert["recovered_at"] = time;
		alert["updated_at"] = time;
		recent[key] = std::move(alert);
		active.erase(key);
	}
}

bool is_active(const json &value) {
