// Use live progress only, never the timestamp selected for historical viewing.
export function getLiveFreshness(updatedAt: number | undefined, receivedAt: number | null, nowSec: number, staleAfterSec: number): LiveFreshness {
  if (updatedAt === undefined && receivedAt === null) return "waiting";
