export type PlaybackStatus = {
  enabled: true;
  mode: "current" | "original";
  state: "playing" | "paused" | "finished" | "stopped";
  speed: number;
  sourceFirst: number;
  sourceLast: number;
  now: number;
};

let anchor: { status: PlaybackStatus; receivedWall: number } | null = null;

export function setPlaybackStatus(status: PlaybackStatus | null) {
  anchor = status ? { status, receivedWall: Date.now() / 1000 } : null;
}

export function dataNowSec() {
  if (!anchor || anchor.status.mode !== "original") return Date.now() / 1000;
  const { status, receivedWall } = anchor;
  return status.state === "playing"
    ? Math.min(status.sourceLast, status.now + Math.max(0, Date.now() / 1000 - receivedWall) * status.speed)
    : status.now;
}

