const source = path.resolve(__dirname, "../client/src/components/StorageHealthSection.tsx");
const compiled = esbuild.buildSync({ entryPoints: [source], bundle: true, platform: "node", format: "cjs", jsx: "automatic", packages: "external", write: false });
const viewModule = new Module(source);
