test("API keeps old snapshots compatible and preserves storage updates", () => {
  const store = new CaptureHealthStore(5);
  assert.equal(store.update(snapshot()), true);
  assert.equal(store.get().storage, undefined);
  let event;
  store.on("update", value => { event = value; });
  assert.equal(store.update(snapshot({ storage })), true);
  assert.deepEqual(store.get().storage, storage);
  assert.deepEqual(event.storage, storage);
});

test("API does not coerce null, negative or invalid capacity into known zero", () => {
  for (const fields of [{ file_bytes: null }, { file_bytes: -1 }, { file_bytes: "0" }, { file_bytes: Infinity }]) {
    const store = new CaptureHealthStore(5);
    store.update(snapshot({ storage: { ...storage, datasets: [{ ...storage.datasets[0], ...fields }] } }));
    assert.equal(store.get().storage.datasets[0].state, "unknown");
    assert.equal(store.get().storage.datasets[0].file_bytes, null);
  }
  for (const fields of [{ total_bytes: 0 }, { available_bytes: null }, { used_percent: 101 }, { used_bytes: 20000 }]) {
    const store = new CaptureHealthStore(5);
    store.update(snapshot({ storage: { ...storage, filesystems: [{ ...storage.filesystems[0], ...fields }] } }));
    assert.equal(store.get().storage.filesystems[0].state, "unknown");
    assert.equal(store.get().storage.filesystems[0].used_percent, null);
  }
});

test("old collector and pending measurements have explicit states in both languages", () => {
  for (const locale of ["en", "ja"]) {
    assert.match(render(undefined, locale), new RegExp(messages["captureHealth.storage.unavailable"][locale]));
    const pending = { ...storage, filesystems: [], datasets: [{ ...storage.datasets[0], state: "unknown", code: "pending", observed_at: 0, file_bytes: null }] };
    assert.match(render(pending, locale), new RegExp(messages["captureHealth.storage.pending"][locale]));
  }
});

test("shared filesystem renders one utilization bar and data size separately", () => {
  for (const locale of ["en", "ja"]) {
    const html = render(storage, locale);
    assert.equal((html.match(/<progress /g) ?? []).length, 1);
    assert.match(html, /2.0 KiB/);
    assert.match(html, /4.0 KiB \/ 10.0 KiB/);
