  }
});

test("failure, stale filesystem, stale dataset, and stopped collector remain visible", () => {
  for (const locale of ["en", "ja"]) {
    for (const code of ["path_missing", "permission_denied", "scan_limit", "nested_filesystem", "unsupported", "cancelled", "io_error"]) {
      const broken = { ...storage, datasets: [{ ...storage.datasets[0], state: "unknown", code, file_bytes: null }] };
      assert.match(render(broken, locale), new RegExp(messages[`captureHealth.storage.error.${code}`][locale]));
    }
