    assert.match(render(storage, locale, { collectorUnavailable: true }), new RegExp(messages["captureHealth.storage.stale"][locale]));
    const customExpiry = { ...storage, collector_stale_after_sec: 20 };
    assert.doesNotMatch(render(customExpiry, locale, { now: now + 6 }), new RegExp(messages["captureHealth.storage.stale"][locale]));
  }
});

test("zero-size directory stays known, identical directories disclose overlap", () => {
  const value = { ...storage, datasets: [{ ...storage.datasets[0], file_bytes: 0, shared_with: ["metrics"] }] };
  for (const locale of ["en", "ja"]) {
    const html = render(value, locale);
    assert.match(html, /0 B/);
    assert.match(html, locale === "en" ? /this value overlaps/ : /この値は重複します/);
  }
