const storage = {
  collector_stale_after_sec: 5, filesystem_interval_sec: 10, dataset_interval_sec: 60,
  filesystems: [{ id: "volume", state: "ok", code: "ok", observed_at: now, dataset_ids: ["capture", "metrics"], paths: ["/data/capture", "/data/metrics"], total_bytes: 10240, used_bytes: 4096, available_bytes: 5120, used_percent: 100 * 4096 / 9216 }],
  datasets: [{ id: "capture", path: "/data/capture", filesystem_id: "volume", state: "ok", code: "ok", observed_at: now, file_bytes: 2048, shared_with: [] }]
};
const snapshot = extra => ({ schema_version: 1, record_type: "capture_health", observed_at: now, host: { id: "fixture" }, overall: { state: "ok", reasons: [] }, interfaces: [], kernel: {}, pipeline: {}, media_network: {}, ...extra });
