const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const net = require("node:net");
const os = require("node:os");
const path = require("node:path");
const { spawn } = require("node:child_process");

const serverEntry = path.resolve(__dirname, "../server/dist/index.js");

async function availablePort() {
  const server = net.createServer();
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

async function waitFor(url, child) {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    if (child.exitCode !== null) throw new Error(`server exited ${child.exitCode}`);
    try {
      const response = await fetch(url);
      if (response.ok) return response;
    } catch { /* Server is still starting. */ }
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  throw new Error("server did not start");
}

test("original playback uses recorded time and blocks runtime mutations", { skip: !fs.existsSync(serverEntry) }, async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-playback-api-"));
  const statusPath = path.join(root, "player-state.json");
  const recordedTime = 1609459200;
  fs.writeFileSync(statusPath, JSON.stringify({
    schema_version: 1, mode: "original", state: "playing", speed: 2,
    source_first: recordedTime, source_last: recordedTime + 60,
    source_anchor: recordedTime, wall_anchor: Date.now() / 1000,
    current_time: recordedTime + 5, record_count: 2, next_index: 1,
    updated_wall: Date.now() / 1000
  }));
  const port = await availablePort();
  const child = spawn(process.execPath, [serverEntry, `--host=127.0.0.1`, `--port=${port}`,
    `--log-dir=${root}`, `--state-dir=${path.join(root, "state")}`], {
    cwd: path.resolve(__dirname, ".."), stdio: ["ignore", "pipe", "pipe"]
  });
  let errorOutput = "";
  child.stderr.on("data", (chunk) => { errorOutput += chunk.toString(); });
  try {
    const base = `http://127.0.0.1:${port}`;
    await waitFor(`${base}/api/playback`, child);
    const playback = await (await fetch(`${base}/api/playback`)).json();
    assert.equal(playback.mode, "original");
    assert.equal(playback.state, "playing");
    assert.ok(playback.now >= recordedTime + 5 && playback.now < recordedTime + 60);
    const timeline = await (await fetch(`${base}/api/timeline`)).json();
    assert.ok(timeline.window.to >= recordedTime + 5 && timeline.window.to < recordedTime + 60);
    const mutation = await fetch(`${base}/api/runtime/restarts/pending`, { method: "POST" });
    assert.equal(mutation.status, 403);
    assert.match((await mutation.json()).error, /disabled during playback/);
  } finally {
    child.kill("SIGTERM");
    await new Promise((resolve) => { if (child.exitCode !== null) resolve(); else child.once("exit", resolve); });
    fs.rmSync(root, { recursive: true, force: true });
  }
  assert.equal(errorOutput, "");
});

test("player journal reaches projected Streams and Events APIs", { skip: !fs.existsSync(serverEntry) || !process.env.STM_PLAYER_BIN || !process.env.STM_PROJECTOR_BIN }, async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-playback-pipeline-"));
  const source = path.join(root, "source");
  const output = path.join(root, "output");
  const recordedTime = 1609459200;
  const journalDir = path.join(source, "event-journal", "20210101");
  const metricsDir = path.join(source, "metrics-journal", "20210101");
  fs.mkdirSync(journalDir, { recursive: true });
  fs.mkdirSync(metricsDir, { recursive: true });
  const producer = { component: "stm", run_id: "pipeline-run", started_at: recordedTime };
  const event = (seq, time, type, sourceFields) => ({ schema_version: 2, record_type: "event",
    capture_id: "pipeline-run", run_id: "pipeline-run", producer, record_id: `pipeline-run:event:${seq}`,
    seq, time, event_time: time, emitted_at: time, type, source: sourceFields });
  fs.writeFileSync(path.join(journalDir, "00.ndjson"), [
    event(0, recordedTime, "run_started", {}),
    event(1, recordedTime + 1, "flow_detected", { stream_key: "stream-a", flow_key: "flow-a", proto: "RTP", label: "Fixture RTP" })
  ].map(JSON.stringify).join("\n") + "\n");
  fs.writeFileSync(path.join(metricsDir, "00.ndjson"), JSON.stringify({ schema_version: 2,
    record_type: "metrics_snapshot", capture_id: "pipeline-run", run_id: "pipeline-run", producer,
    record_id: "pipeline-run:metrics:0", seq: 0, time: recordedTime + 2,
    emitted_at: recordedTime + 2, metrics: [], interfaces: [] }) + "\n");
  const run = (binary, args) => {
    const result = require("node:child_process").spawnSync(binary, args, { encoding: "utf8", timeout: 10000 });
    assert.equal(result.status, 0, result.stderr || result.stdout);
  };
  let child;
  try {
    run(process.env.STM_PLAYER_BIN, [`--source=${source}`, `--output=${output}`, "--time-mode=original", "--speed=10000"]);
    run(process.env.STM_PROJECTOR_BIN, [`--log-dir=${output}`, `--output-dir=${path.join(output, "derived")}`, "--retention-hours=0", "--once"]);
    const port = await availablePort();
    child = spawn(process.execPath, [serverEntry, "--host=127.0.0.1", `--port=${port}`,
      `--log-dir=${output}`, `--state-dir=${path.join(root, "fe-state")}`], {
      cwd: path.resolve(__dirname, ".."), stdio: ["ignore", "pipe", "pipe"]
    });
    const base = `http://127.0.0.1:${port}`;
    await waitFor(`${base}/api/playback`, child);
    const bootstrap = await (await fetch(`${base}/api/bootstrap`)).json();
    assert.ok(bootstrap.streams.some((item) => item.streamKey === "stream-a"));
    assert.ok(bootstrap.events.some((item) => item.type === "flow_detected"));
    const live = await (await fetch(`${base}/api/live`)).json();
    assert.equal(live.observedAt, recordedTime + 2);
    const history = await (await fetch(`${base}/api/events?from=${recordedTime}&to=${recordedTime + 3}`)).json();
    assert.ok(history.some((item) => item.type === "flow_detected"));
  } finally {
    if (child) {
      child.kill("SIGTERM");
      await new Promise((resolve) => { if (child.exitCode !== null) resolve(); else child.once("exit", resolve); });
    }
    fs.rmSync(root, { recursive: true, force: true });
  }
});
import type { Server as HttpServer } from "node:http";
import { WebSocketServer, type WebSocket } from "ws";
import type { StreamStore } from "../state/store";
import type { AppConfig, WsMessage } from "../types";
import type { CaptureHealthStore } from "../captureHealth";
import { playbackStatus } from "../playbackClock";

export class SocketServer {
  private readonly wss = new WebSocketServer({ noServer: true });
  private readonly metricSubscriptions = new Map<WebSocket, string>();
  private pendingStreams = false;
  private connectionHeartbeatTimer: NodeJS.Timeout | null = null;
  private maintenanceTimer: NodeJS.Timeout | null = null;
  private streamSeq = 0;
  private lastStreams = new Map<string, string>();

  constructor(
    private readonly server: HttpServer,
    private readonly store: StreamStore,
    private readonly captureHealth: CaptureHealthStore,
    private readonly streamsPatchIntervalMs = 250,
    private readonly maxBufferedBytes = 8 * 1024 * 1024
  ) {}

  start() {
    this.server.on("upgrade", (request, socket, head) => {
      if (request.url !== "/ws") return;
      this.wss.handleUpgrade(request, socket, head, (ws) => {
        this.wss.emit("connection", ws, request);
      });
    });

    this.wss.on("connection", (ws) => {
      this.send(ws, {
        type: "snapshot",
        streams: this.store.listStreams(),
        interfaces: this.store.listInterfaces(),
        timeline: [],
        summary: this.store.getSummary(),
        captureHealth: this.captureHealth.get(),
        streamsSeq: this.streamSeq
      });
      const replay = playbackStatus();
      if (replay) this.send(ws, { type: "playback:status", playback: { enabled: true, ...replay } });
      ws.on("message", (raw) => this.handleClientMessage(ws, raw.toString()));
      ws.on("close", () => this.metricSubscriptions.delete(ws));
    });

    this.store.on("streams:update", () => this.scheduleStreamsUpdate());
    this.store.on("metrics:update", (streamKey: string) => this.broadcastSubscribedMetrics(streamKey));
    this.captureHealth.on("update", (captureHealth) => this.broadcast({ type: "capture-health:update", captureHealth }));

    this.store.on("events:update", (event) => {
      this.broadcast({ type: "events:update", events: [event] });
    });

    this.maintenanceTimer = setInterval(() => {
      this.store.tick();
      const replay = playbackStatus();
      if (replay) this.broadcast({ type: "playback:status", playback: { enabled: true, ...replay } });
    }, 1000);
    this.maintenanceTimer.unref?.();
    this.connectionHeartbeatTimer = setInterval(() => this.broadcast({ type: "connection:heartbeat" }), 5000);
    this.connectionHeartbeatTimer.unref?.();
  }

  broadcastConfig(config: AppConfig) {
    this.broadcast({ type: "config:update", config });
  }

  broadcastLiveHeartbeat() {
    this.broadcast({ type: "live:heartbeat" });
  }


  private scheduleStreamsUpdate() {
    if (this.pendingStreams) return;
    this.pendingStreams = true;
    setTimeout(() => {
      this.pendingStreams = false;
      const streams = this.store.listStreams();
      const order = streams.map((s) => s.streamKey);
      const nextMap = new Map<string, string>();
      const upserts = [];
      for (const stream of streams) {
        const encoded = JSON.stringify(stream);
        nextMap.set(stream.streamKey, encoded);
        if (this.lastStreams.get(stream.streamKey) !== encoded) {
          upserts.push(stream);
        }
      }
      const removes: string[] = [];
      for (const key of this.lastStreams.keys()) {
        if (!nextMap.has(key)) removes.push(key);
      }
      if (upserts.length === 0 && removes.length === 0) return;
      this.lastStreams = nextMap;
      this.streamSeq += 1;
      this.broadcast({
        type: "streams:patch",
        seq: this.streamSeq,
        upserts,
        removes,
        order,
        interfaces: this.store.listInterfaces(),
        summary: this.store.getSummary()
      });
    }, Math.max(50, this.streamsPatchIntervalMs));
  }

  private broadcast(message: WsMessage) {
    const clients = [...this.wss.clients].filter((client) => client.readyState === client.OPEN);
    if (clients.length === 0) return;
    const payload = JSON.stringify(message);
    for (const client of clients) this.safeSend(client, payload);
  }

  private broadcastSubscribedMetrics(streamKey: string) {
    const clients = [...this.wss.clients].filter((client) =>
      client.readyState === client.OPEN && this.metricSubscriptions.get(client) === streamKey
    );
    if (clients.length === 0) return;

    const metrics = this.store.getMetrics(streamKey);
    if (!metrics) return;

    const payload = JSON.stringify({ type: "stream:metrics", streamKey, metrics } satisfies WsMessage);
    for (const client of clients) this.safeSend(client, payload);
  }

  private handleClientMessage(client: WebSocket, raw: string) {
    try {
      const message = JSON.parse(raw) as { type?: string; streamKey?: unknown };
      if (message.type !== "stream:subscribe") return;
      if (typeof message.streamKey === "string" && message.streamKey.length > 0) {
        this.metricSubscriptions.set(client, message.streamKey);
      } else {
        this.metricSubscriptions.delete(client);
      }
    } catch {
      // Ignore malformed client messages; the connection can continue receiving snapshots.
    }
  }

  private send(client: WebSocket, message: WsMessage) {
    if (client.readyState === client.OPEN) this.safeSend(client, JSON.stringify(message));
  }

  private safeSend(client: WebSocket, payload: string) {
    if (client.bufferedAmount > this.maxBufferedBytes) {
      this.metricSubscriptions.delete(client);
      client.terminate();
      return;
    }
    client.send(payload);
  }
}
import { readFileSync } from "node:fs";
import { config } from "./config";

export type PlaybackStatus = {
  mode: "current" | "original";
  state: "playing" | "paused" | "finished" | "stopped";
  speed: number;
  sourceFirst: number;
  sourceLast: number;
  now: number;
};

type PlayerState = {
  schema_version: number;
  mode: PlaybackStatus["mode"];
  state: PlaybackStatus["state"];
  speed: number;
  source_first: number;
  source_last: number;
  current_time: number;
  updated_wall: number;
};

export function playbackEnabled() { return Boolean(config.playbackStateFile); }

export function playbackStatus(): PlaybackStatus | null {
  if (!config.playbackStateFile) return null;
  try {
    const state = JSON.parse(readFileSync(config.playbackStateFile, "utf8")) as PlayerState;
    if (state.schema_version !== 1 || !["current", "original"].includes(state.mode) ||
      !["playing", "paused", "finished", "stopped"].includes(state.state) ||
      !Number.isFinite(state.speed) || state.speed <= 0 || !Number.isFinite(state.current_time) ||
      !Number.isFinite(state.updated_wall)) return null;
    const elapsed = Math.max(0, Date.now() / 1000 - state.updated_wall);
    const now = state.state === "playing"
      ? state.mode === "original" ? Math.min(state.source_last, state.current_time + elapsed * state.speed) : state.current_time + elapsed
      : state.current_time;
    return { mode: state.mode, state: state.state, speed: state.speed,
      sourceFirst: state.source_first, sourceLast: state.source_last, now };
  } catch { return null; }
}

export function dataNowSec() {
  const status = playbackStatus();
  return status?.mode === "original" ? status.now : Date.now() / 1000;
}

