# stm_player: 保存済みデータの再生

`stm_player`は保存済み`event-journal/`と`metrics-journal/`を観測時刻順に別のrootへ書き出します。`stm_projector`とFE serverはそのrootを監視します。元の記録は変更しません。PCAPのパケット再解析とcapture-healthの再生は対象外です。

## 準備と起動

記録一式を変更しないディレクトリに固定します。出力rootは存在しないか空である必要があります。各回の再生には新しいrootを指定してください。通常運用の`/tmp/stm`は出力先にできません。

```sh
cmake -S be/src -B be/build -DCMAKE_BUILD_TYPE=Release
cmake --build be/build --target stm_player stm_projector

# ターミナル1: 状態ファイルと制御ソケットを作り、再生開始を待つ
./be/build/stm_player --source=/tmp/stm-recordings/case-a \
  --output=/tmp/stm-replay/case-a --time-mode=original --speed=1 --start-paused

# ターミナル2: projectorの出力先を明示する
./be/build/stm_projector --log-dir=/tmp/stm-replay/case-a \
  --output-dir=/tmp/stm-replay/case-a/derived --retention-hours=0

# ターミナル3: FEの保存設定も通常運用から分離する
cd fe
npm run dev -w server -- --log-dir=/tmp/stm-replay/case-a \
  --state-dir=/tmp/stm-replay-state/case-a

# ターミナル4: 再生開始
./be/build/stm_player --output=/tmp/stm-replay/case-a --command=resume
```

クライアント開発サーバーは`cd fe && npm run dev -w client`で起動します。FE serverは起動時に`<log-dir>/player-state.json`を検出すると再生モードになります。別の状態ファイルを使う場合は`--playback-state-file=<path>`を指定します。再生モードではデータ時刻にplayerの時計を使い、`GET /api/playback`で状態を返します。通常の設定・実プロセス変更APIは403を返し、Dashboard/Inspectorレイアウトの保存だけは隔離した`--state-dir`へ許可します。

`--time-mode=current`では記録時刻を再生開始時の現在へ移し、`--time-mode=original`では日時を保持します。既定は`current`です。`--speed`は正の数値を指定します。両モードとも記録間隔を指定速度で再生します。`original`では一時停止中に画面のデータ時計も停止します。`current`では一時停止後の再開時に遅れたレコードを追い付くまで順次出力し、既に書いた時刻との対応を維持します。

```sh
./be/build/stm_player --output=/tmp/stm-replay/case-a --command=status
./be/build/stm_player --output=/tmp/stm-replay/case-a --command=pause
./be/build/stm_player --output=/tmp/stm-replay/case-a --command=resume
./be/build/stm_player --output=/tmp/stm-replay/case-a --command=stop
```

先頭から再生する場合は、player、projector、FE serverを停止して新しい出力rootとFE state-dirで起動します。古いrootを自動削除しません。playerは入力ファイルのサイズ・変更時刻を再生中に検査し、manifestにファイルのサイズ・ハッシュ・件数を残します。

projectorのTopology full snapshot公開は実際の処理間隔で間引かれます。同じjournalから得られるライフサイクルとメトリクスは同じですが、混雑度が違う実行環境ではTopology snapshotの公開数と境界が変わる場合があります。完全に同じ描画更新列が必要な試験には、投影済みデータのトレース再生またはprojectorの再生時計対応が必要です。
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <csignal>
#include <cstdio>
#include <cstdint>
#include <ctime>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <map>
#include <memory>
#include <poll.h>
#include <sstream>
#include <stdexcept>
#include <string>
#include <string_view>
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>
#include <vector>

#include "json.h"

namespace fs = std::filesystem;
using json = nlohmann::json;
using steady_clock = std::chrono::steady_clock;

namespace {
volatile std::sig_atomic_t interrupted = 0;
void stop_signal(int) { interrupted = 1; }

double wall_now() {
  return std::chrono::duration<double>(std::chrono::system_clock::now().time_since_epoch()).count();
}

struct options {
  fs::path source;
  fs::path output;
  fs::path control_socket;
  std::string mode{"current"};
  std::string command;
  double speed{1.0};
  bool start_paused{false};
};

options parse_args(int argc, char **argv) {
  options result;
  for(int i = 1; i < argc; ++i) {
    const std::string arg = argv[i];
    if(arg == "--start-paused") { result.start_paused = true; continue; }
    const auto equal = arg.find('=');
    if(equal == std::string::npos || arg.rfind("--", 0) != 0) throw std::runtime_error("invalid option: " + arg);
    const auto key = arg.substr(2, equal - 2);
    const auto value = arg.substr(equal + 1);
    if(key == "source") result.source = value;
    else if(key == "output") result.output = value;
    else if(key == "control-socket") result.control_socket = value;
    else if(key == "time-mode") result.mode = value;
    else if(key == "speed") result.speed = std::stod(value);
    else if(key == "command") result.command = value;
    else throw std::runtime_error("unknown option: " + key);
  }
  if(result.mode != "current" && result.mode != "original") throw std::runtime_error("time-mode must be current or original");
  if(!std::isfinite(result.speed) || result.speed <= 0) throw std::runtime_error("speed must be positive");
  if(result.command.empty() && (result.source.empty() || result.output.empty())) throw std::runtime_error("--source and --output are required");
  if(!result.command.empty() && result.command != "pause" && result.command != "resume" && result.command != "status" && result.command != "stop") throw std::runtime_error("invalid command");
  if(result.control_socket.empty() && !result.output.empty()) result.control_socket = result.output / "player.sock";
  if(!result.command.empty() && result.control_socket.empty()) throw std::runtime_error("--output or --control-socket is required for a command");
  return result;
}

struct input_record {
  double time;
  std::size_t file_index;
  std::uint64_t offset;
  std::size_t ordinal;
  bool event;
};

struct source_file {
  fs::path path;
  std::uintmax_t size;
  fs::file_time_type modified;
  std::uint64_t hash;
  std::size_t records;
};

std::string hex_hash(std::uint64_t value) {
  std::ostringstream stream;
  stream << std::hex << std::setw(16) << std::setfill('0') << value;
  return stream.str();
}

void scan_root(const fs::path &root, bool event, std::vector<source_file> &files, std::vector<input_record> &records) {
  if(!fs::is_directory(root)) throw std::runtime_error("missing journal directory: " + root.string());
  std::vector<fs::path> paths;
  for(const auto &entry : fs::recursive_directory_iterator(root)) {
    if(entry.is_regular_file() && entry.path().extension() == ".ndjson") paths.push_back(entry.path());
  }
  std::sort(paths.begin(), paths.end());
  for(const auto &path : paths) {
    const auto index = files.size();
    source_file file{path, fs::file_size(path), fs::last_write_time(path), 14695981039346656037ULL, 0};
    std::ifstream input(path, std::ios::binary);
    if(!input) throw std::runtime_error("cannot read: " + path.string());
    std::string line;
    while(true) {
      const auto position = input.tellg();
      if(!std::getline(input, line)) break;
      for(unsigned char byte : line) { file.hash ^= byte; file.hash *= 1099511628211ULL; }
      file.hash ^= '\n'; file.hash *= 1099511628211ULL;
      if(line.empty()) continue;
      const json value = json::parse(line);
      if(!value.is_object() || value.value("schema_version", 0) != 2 ||
         value.value("record_type", std::string{}) != (event ? "event" : "metrics_snapshot") ||
         !value.contains("record_id") || !value["record_id"].is_string())
        throw std::runtime_error("invalid journal record in " + path.string());
      const auto field = event ? "event_time" : "time";
      if(!value.contains(field) || !value[field].is_number()) throw std::runtime_error("missing record time in " + path.string());
      const double time = value[field].get<double>();
      if(!std::isfinite(time) || time <= 0) throw std::runtime_error("invalid record time in " + path.string());
      records.push_back({time, index, static_cast<std::uint64_t>(position), records.size(), event});
      ++file.records;
    }
    if(fs::file_size(path) != file.size || fs::last_write_time(path) != file.modified)
      throw std::runtime_error("input changed during scan: " + path.string());
    files.push_back(file);
  }
}

void transform_known_times(json &value, double source_anchor, double output_anchor, double speed) {
  static const std::array<std::string_view, 10> keys{
    "event_time", "started_at", "updated_at", "recovered_at", "last_error_time",
    "last_seen_time", "first_seen", "last_seen", "start_time", "end_time"
  };
  if(value.is_array()) {
    for(auto &child : value) transform_known_times(child, source_anchor, output_anchor, speed);
  } else if(value.is_object()) {
    for(auto &[key, child] : value.items()) {
      if(child.is_number() && std::find(keys.begin(), keys.end(), key) != keys.end()) {
        const double epoch = child.get<double>();
        if(epoch > 0.0 && std::isfinite(epoch)) child = output_anchor + (epoch - source_anchor) / speed;
      } else if(child.is_array() || child.is_object()) {
        transform_known_times(child, source_anchor, output_anchor, speed);
      }
    }
  }
}

void transform_times(json &record, double source_anchor, double output_anchor, double speed) {
  for(const auto *key : {"time", "event_time", "emitted_at"}) {
    if(record.contains(key) && record[key].is_number()) {
      const double epoch = record[key].get<double>();
      if(epoch > 0.0 && std::isfinite(epoch)) record[key] = output_anchor + (epoch - source_anchor) / speed;
    }
  }
  for(const auto *key : {"producer", "source", "detail", "metrics", "interfaces"}) {
    if(record.contains(key)) transform_known_times(record[key], source_anchor, output_anchor, speed);
  }
}

std::string hour_path(double epoch) {
  const std::time_t seconds = static_cast<std::time_t>(epoch);
  std::tm utc{};
  gmtime_r(&seconds, &utc);
  char buffer[32];
  std::strftime(buffer, sizeof(buffer), "%Y%m%d/%H.ndjson", &utc);
  return buffer;
}

void atomic_json(const fs::path &path, const json &value) {
  const auto temporary = path.string() + ".tmp";
  {
    std::ofstream output(temporary, std::ios::trunc);
    if(!output) throw std::runtime_error("cannot write: " + temporary);
    output << value.dump(2) << '\n';
    output << value.dump(2) << '\n';
    output.flush();
    if(!output) throw std::runtime_error("cannot flush: " + temporary);
  }
  fs::rename(temporary, path);
}

json send_command(const fs::path &socket_path, const std::string &command) {
  int fd = socket(AF_UNIX, SOCK_STREAM, 0);
  if(fd < 0) throw std::runtime_error("cannot create control socket");
  sockaddr_un address{};
  address.sun_family = AF_UNIX;
  if(socket_path.string().size() >= sizeof(address.sun_path)) { close(fd); throw std::runtime_error("control socket path too long"); }
  std::snprintf(address.sun_path, sizeof(address.sun_path), "%s", socket_path.c_str());
  if(connect(fd, reinterpret_cast<sockaddr*>(&address), sizeof(address)) != 0) { close(fd); throw std::runtime_error("cannot connect to player"); }
  const std::string request = command + "\n";
  (void)write(fd, request.data(), request.size());
  std::string response;
  char buffer[1024];
  for(;;) {
    const auto size = read(fd, buffer, sizeof(buffer));
    if(size <= 0) break;
    response.append(buffer, static_cast<std::size_t>(size));
  }
  close(fd);
  return json::parse(response);
}

class player {
public:
  explicit player(options opts) : opts_(std::move(opts)) {
    const auto source = fs::canonical(opts_.source);
    const auto output = fs::weakly_canonical(opts_.output);
    if(output == source || output.string().starts_with(source.string() + "/") || source.string().starts_with(output.string() + "/"))
      throw std::runtime_error("source and output must be separate directories");
    if(fs::exists(output) && !fs::is_empty(output)) throw std::runtime_error("output directory must be empty: " + output.string());
    if(output == "/tmp/stm" || output.string().starts_with("/tmp/stm/"))
      throw std::runtime_error("refusing to write production /tmp/stm");
    opts_.source = source;
    opts_.output = output;
    scan_root(source / "event-journal", true, files_, records_);
    scan_root(source / "metrics-journal", false, files_, records_);
    if(records_.empty()) throw std::runtime_error("no journal records found");
    std::stable_sort(records_.begin(), records_.end(), [](const auto &left, const auto &right) {
      if(left.time != right.time) return left.time < right.time;
      if(left.event != right.event) return left.event;
      return left.ordinal < right.ordinal;
    });
    first_ = records_.front().time;
    last_ = records_.back().time;
    source_anchor_ = first_;
    output_anchor_ = wall_now();
    steady_anchor_ = steady_clock::now();
    paused_ = opts_.start_paused;
    paused_source_ = first_;
    fs::create_directories(output);
    write_manifest();
    write_state();
    open_socket();
  }

  ~player() {
    if(socket_fd_ >= 0) close(socket_fd_);
    std::error_code error;
    fs::remove(opts_.control_socket, error);
  }

  int run() {
    while(!interrupted && !stopped_ && next_ < records_.size()) {
      if(!paused_ && source_now() >= records_[next_].time) {
        emit(records_[next_]);
        ++next_;
        write_state();
        continue;
      }
      const double wait_sec = paused_ ? 1.0 : std::max(0.0, (records_[next_].time - source_now()) / opts_.speed);
      const int timeout = static_cast<int>(std::clamp(wait_sec * 1000, 0.0, 1000.0));
      pollfd descriptor{socket_fd_, POLLIN, 0};
      if(poll(&descriptor, 1, timeout) > 0 && (descriptor.revents & POLLIN)) handle_client();
      if(steady_clock::now() - last_state_write_ >= std::chrono::seconds(1)) write_state();
    }
    finished_ = next_ == records_.size();
    stopped_ = stopped_ || interrupted;
    write_state();
    return 0;
  }

private:
  double source_now() const {
    if(paused_) return paused_source_;
    return source_anchor_ + std::chrono::duration<double>(steady_clock::now() - steady_anchor_).count() * opts_.speed;
  }

  json status() const {
    const double source_time = finished_ ? last_ : std::min(last_, source_now());
    return json{
      {"schema_version", 1}, {"mode", opts_.mode}, {"state", finished_ ? "finished" : stopped_ ? "stopped" : paused_ ? "paused" : "playing"},
      {"speed", opts_.speed}, {"source_first", first_}, {"source_last", last_},
      {"source_anchor", source_anchor_}, {"wall_anchor", output_anchor_},
      {"current_time", opts_.mode == "original" ? source_time : output_anchor_ + (source_time - source_anchor_) / opts_.speed},
      {"record_count", records_.size()}, {"next_index", next_}, {"updated_wall", wall_now()}
    };
  }

  void write_state() {
    atomic_json(opts_.output / "player-state.json", status());
    last_state_write_ = steady_clock::now();
  }

  void write_manifest() const {
    json files = json::array();
    for(const auto &file : files_) files.push_back({{"path", fs::relative(file.path, opts_.source).generic_string()}, {"size", file.size}, {"hash_fnv1a64", hex_hash(file.hash)}, {"records", file.records}});
    atomic_json(opts_.output / "player-manifest.json", json{{"schema_version", 1}, {"source", opts_.source.string()}, {"mode", opts_.mode}, {"speed", opts_.speed}, {"source_first", first_}, {"source_last", last_}, {"files", files}});
  }

  void emit(const input_record &record) {
    const auto &file = files_[record.file_index];
    if(fs::file_size(file.path) != file.size || fs::last_write_time(file.path) != file.modified)
      throw std::runtime_error("input changed during playback: " + file.path.string());
    std::ifstream input(file.path, std::ios::binary);
    input.seekg(static_cast<std::streamoff>(record.offset));
    std::string line;
    if(!std::getline(input, line)) throw std::runtime_error("cannot reread journal record");
    json value = json::parse(line);
    const double output_time = opts_.mode == "current" ? output_anchor_ + (record.time - source_anchor_) / opts_.speed : record.time;
    if(opts_.mode == "current") transform_times(value, source_anchor_, output_anchor_, opts_.speed);
    const auto path = opts_.output / (record.event ? "event-journal" : "metrics-journal") / hour_path(output_time);
    const auto key = path.string();
    if(!streams_.contains(key)) {
      fs::create_directories(path.parent_path());
      auto stream = std::make_unique<std::ofstream>(path, std::ios::app);
      if(!*stream) throw std::runtime_error("cannot write journal: " + key);
      streams_.emplace(key, std::move(stream));
    }
    auto &stream = *streams_.at(key);
    stream << value.dump() << '\n';
    stream.flush();
    if(!stream) throw std::runtime_error("journal write failed: " + key);
  }

  void open_socket() {
    socket_fd_ = socket(AF_UNIX, SOCK_STREAM, 0);
    if(socket_fd_ < 0) throw std::runtime_error("cannot create control socket");
    sockaddr_un address{};
    address.sun_family = AF_UNIX;
    if(opts_.control_socket.string().size() >= sizeof(address.sun_path)) throw std::runtime_error("control socket path too long");
    std::snprintf(address.sun_path, sizeof(address.sun_path), "%s", opts_.control_socket.c_str());
    if(bind(socket_fd_, reinterpret_cast<sockaddr*>(&address), sizeof(address)) != 0 || listen(socket_fd_, 4) != 0)
      throw std::runtime_error("cannot bind control socket: " + opts_.control_socket.string());
  }

  void handle_client() {
    const int client = accept(socket_fd_, nullptr, nullptr);
    if(client < 0) return;
    char buffer[64]{};
    const auto length = read(client, buffer, sizeof(buffer) - 1);
    std::string command = length > 0 ? std::string(buffer, static_cast<std::size_t>(length)) : "";
    command = command.substr(0, command.find_first_of("\r\n"));
    json answer;
    if(command == "pause" && !paused_) {
      paused_source_ = source_now();
      paused_ = true;
    } else if(command == "resume" && paused_) {
      if(opts_.mode == "original" || next_ == 0) {
        source_anchor_ = paused_source_;
        steady_anchor_ = steady_clock::now();
        if(opts_.mode == "current") output_anchor_ = wall_now();
      }
      paused_ = false;
    } else if(command == "stop") {
      stopped_ = true;
    } else if(command != "status" && command != "pause" && command != "resume") {
      answer = {{"error", "unknown command"}};
    }
    if(answer.is_null()) { write_state(); answer = status(); }
    const auto response = answer.dump();
    (void)write(client, response.data(), response.size());
    close(client);
  }

  options opts_;
  std::vector<source_file> files_;
  std::vector<input_record> records_;
  std::map<std::string, std::unique_ptr<std::ofstream>> streams_;
  double first_{0};
  double last_{0};
  double source_anchor_{0};
  double output_anchor_{0};
  double paused_source_{0};
  steady_clock::time_point steady_anchor_{};
  steady_clock::time_point last_state_write_{};
  std::size_t next_{0};
  int socket_fd_{-1};
  bool paused_{false};
  bool stopped_{false};
  bool finished_{false};
};
} // namespace

int main(int argc, char **argv) {
  std::signal(SIGINT, stop_signal);
  std::signal(SIGTERM, stop_signal);
  try {
    const auto opts = parse_args(argc, argv);
    if(!opts.command.empty()) {
      const auto response = send_command(opts.control_socket, opts.command);
      std::cout << response.dump(2) << '\n';
      return response.contains("error") ? 1 : 0;
    }
    return player(opts).run();
  } catch(const std::exception &error) {
    std::cerr << "stm_player: " << error.what() << '\n';
    return 1;
  }
}

