import { RuntimeStatusProvider } from "./runtimeStatus";
import { setPlaybackStatus, type PlaybackStatus } from "./playbackClock";

async function start() {
  try {
    const response = await fetch("/api/playback", { signal: AbortSignal.timeout(2000) });
    if (response.ok) {
      const status = await response.json() as { enabled: false } | PlaybackStatus;
      setPlaybackStatus(status.enabled ? status : null);
    }
  } catch { /* The regular server availability flow handles connection errors. */ }
  ReactDOM.createRoot(document.getElementById("root")!).render(
    <React.StrictMode>
      <I18nProvider><RuntimeStatusProvider><App /></RuntimeStatusProvider></I18nProvider>
    </React.StrictMode>
  );
}

void start();
export type PlaybackStatus = {
  enabled: true;
  mode: "current" | "original";
  state: "playing" | "paused" | "finished" | "stopped";
  speed: number;
  sourceFirst: number;
  sourceLast: number;
  now: number;
};

let anchor: { status: PlaybackStatus; receivedWall: number } | null = null;

export function setPlaybackStatus(status: PlaybackStatus | null) {
  anchor = status ? { status, receivedWall: Date.now() / 1000 } : null;
}

export function dataNowSec() {
  if (!anchor || anchor.status.mode !== "original") return Date.now() / 1000;
  const { status, receivedWall } = anchor;
  return status.state === "playing"
    ? Math.min(status.sourceLast, status.now + Math.max(0, Date.now() / 1000 - receivedWall) * status.speed)
    : status.now;
}
