import { useEffect, useState } from "react";
import type { CaptureHealthStorage } from "../types/api";
import { useI18n } from "../i18n";
import { formatRelativeTime } from "./format";

type Translate = (key: string, values?: Record<string, string | number>) => string;

export function StorageHealthSection({ storage, observedAt, collectorUnavailable }: { storage?: CaptureHealthStorage; observedAt: number; collectorUnavailable: boolean }) {
  const { t } = useI18n();
  const [now, setNow] = useState(() => Date.now() / 1000);
  useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now() / 1000), 1000);
    return () => window.clearInterval(timer);
  }, []);
  return <StorageHealthView storage={storage} observedAt={observedAt} collectorUnavailable={collectorUnavailable} now={now} t={t} />;
}

export function StorageHealthView({ storage, observedAt, collectorUnavailable = false, now, t }: { storage?: CaptureHealthStorage; observedAt: number; collectorUnavailable?: boolean; now: number; t: Translate }) {
  const collectorStale = collectorUnavailable || now - observedAt > (storage?.collector_stale_after_sec ?? 5);
  const datasetName = (id: string) => ["capture", "events", "metrics", "derived"].includes(id) ? t(`captureHealth.storage.dataset.${id}`) : id;
  const status = (state: string, code: string, timestamp: number, lifetime: number) => {
    if (code === "pending") return t("captureHealth.storage.pending");
    if (collectorStale || timestamp <= 0 || now - timestamp > lifetime) return t("captureHealth.storage.stale");
    if (state === "ok") return "";
    return t(`captureHealth.storage.error.${["path_missing", "permission_denied", "scan_limit", "nested_filesystem", "unsupported", "cancelled"].includes(code) ? code : "io_error"}`);
  };
  return <section className="capture-health-section capture-health-storage">
    <header><h3>{t("captureHealth.storage.title")}</h3><span>{t("captureHealth.storage.live")}</span></header>
    {!storage ? <p className="capture-health-storage-note">{t("captureHealth.storage.unavailable")}</p> : <>
      <p className="capture-health-storage-note">{t("captureHealth.storage.filesystemNote")}</p>
      <div className="capture-health-storage-filesystems">
        {storage.filesystems.length === 0 && <p className="capture-health-storage-note">{t("captureHealth.storage.pending")}</p>}
        {storage.filesystems.map(item => {
          const message = status(item.state, item.code, item.observed_at, storage.filesystem_interval_sec * 3);
          return <div key={item.id} className={`capture-health-storage-volume${message ? " is-unavailable" : ""}`}>
            <div className="capture-health-storage-volume-heading"><strong>{item.dataset_ids.map(datasetName).join(" · ")}</strong><span>{message || t("captureHealth.storage.usedPercent", { value: item.used_percent?.toFixed(1) ?? "-" })}</span></div>
            {item.state === "ok" && item.used_percent !== null ? <progress aria-label={t("captureHealth.storage.utilization")} max={100} value={item.used_percent} /> : <div className="capture-health-storage-bar-empty" />}
            <dl className="capture-health-definition"><div><dt>{t("captureHealth.storage.usedTotal")}</dt><dd>{bytes(item.used_bytes)} / {bytes(item.total_bytes)}</dd></div><div><dt>{t("captureHealth.storage.available")}</dt><dd>{bytes(item.available_bytes)}</dd></div></dl>
            <div className="capture-health-storage-volume-footer"><span title={item.paths.join("\n")}>{item.paths.join(" · ")}</span><span>{updated(item.observed_at, t)}</span></div>
          </div>;
        })}
      </div>
      <div className="capture-health-storage-datasets">
        <div className="capture-health-storage-datasets-heading"><strong>{t("captureHealth.storage.fileTotals")}</strong><span>{t("captureHealth.storage.fileNote")}</span></div>
        {storage.datasets.map(item => {
          const message = status(item.state, item.code, item.observed_at, storage.dataset_interval_sec * 5);
          return <div key={item.id} className={`capture-health-storage-dataset${message ? " is-unavailable" : ""}`}>
            <div><strong>{datasetName(item.id)}</strong><small title={item.path}>{item.path}</small>{item.shared_with.length > 0 && <small>{t("captureHealth.storage.shared", { names: item.shared_with.map(datasetName).join(" · ") })}</small>}</div>
            <strong>{bytes(item.file_bytes)}</strong><div className="capture-health-storage-dataset-status">{message && <span>{message}</span>}<small>{updated(item.observed_at, t)}</small></div>
          </div>;
        })}
      </div>
    </>}
  </section>;
}

function bytes(value: number | null): string {
  if (value === null || !Number.isFinite(value) || value < 0) return "-";
  const units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
  const index = value > 0 ? Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1) : 0;
  return `${(value / 1024 ** index).toFixed(index === 0 ? 0 : 1)} ${units[index]}`;
}

function updated(timestamp: number, t: Translate) {
  return timestamp > 0 ? t("captureHealth.storage.updated", { time: formatRelativeTime(timestamp) }) : t("captureHealth.storage.pending");
}
