type AnyRecord = Record<string, any>;

export function normalizeEventLine(line: string): EventLogItem | undefined {
  const raw = JSON.parse(line) as AnyRecord;
  const time = Number(raw.time ?? Date.now() / 1000);
  const type = String(raw.type ?? "event");
  const source = raw.source ?? {};
  const detail = raw.detail;
  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
  const proto = source.proto ? String(source.proto) : undefined;
  const interfaceId = numericInterfaceId(source.interface_id) ?? interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey);
  return {
    id: typeof raw.record_id === "string" && raw.record_id ? raw.record_id : `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
    time,
    type,
    level: levelForType(type, detail),
    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
    proto,
    interfaceId,
    streamKey,
    flowKey,
    targetLabel: targetLabel(source, streamKey, flowKey, detail),
    message: messageForType(type, detail),
    detail
  };
}

function levelForType(type: string, detail: unknown): EventLogItem["level"] {
  if (type === "capture_health_state_changed") {
    const state = stringValue(recordValue(detail)?.to);
    if (state === "critical") return "error";
    if (state === "warning" || state === "unknown") return "warn";
  }
  if (type.endsWith("_recovered") || type === "alert_data_available") return "info";
  if (type === "alert_detected" || type === "alert_data_unavailable") {
    const severity = stringValue(recordValue(detail)?.severity)?.toLowerCase();
    if (severity === "error" || severity === "critical") return "error";
    if (severity === "warning" || severity === "warn") return "warn";
  }
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string, detail?: AnyRecord) {
  if (type === "transport_reclassified") {
    const from = stringValue(recordValue(detail)?.from?.proto) ?? "transport";
    const to = stringValue(recordValue(detail)?.to?.proto) ?? "specialized protocol";
    return `${from} → ${to} reclassified`;
  }
  const alertMessage = alertMessageForType(type, detail);
  if (alertMessage) return alertMessage;
  return type
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function alertMessageForType(type: string, detail?: AnyRecord) {
  if (type !== "alert_detected" && type !== "alert_recovered") return undefined;
  const record = recordValue(detail);
  const metric = stringValue(record?.metric);
  const value = numericValue(record?.value);
  const operator = comparisonOperator(stringValue(record?.comparison_operator) ?? stringValue(record?.operator));
  const trigger = numericValue(record?.error_threshold) ?? numericValue(record?.threshold);
  const recovery = numericValue(record?.recover_threshold) ?? numericValue(record?.threshold);
  if (!metric && value === undefined && !operator && trigger === undefined && recovery === undefined) return undefined;

  const detected = type === "alert_detected";
  const threshold = detected ? trigger : recovery;
  const conditionOperator = detected ? operator : inverseComparisonOperator(operator);
  const title = detected ? "Alert Detected" : "Alert Recovered";
  if (metric && value !== undefined && threshold !== undefined && conditionOperator) {
    return `${title} | ${metric}: ${formatAlertMetricValue(metric, value)} ${conditionOperator} ${formatAlertMetricValue(metric, threshold)}`;
  }

  const parts = [title];
  if (metric && value !== undefined) parts.push(`${metric}: ${formatAlertMetricValue(metric, value)}`);
  else if (metric) parts.push(metric);
  else if (value !== undefined) parts.push(formatAlertMetricValue(metric, value));
  return parts.join(" | ");
}

function comparisonOperator(value: string | undefined) {
  return [">", ">=", "<", "<=", "==", "!="].includes(value ?? "") ? value : undefined;
}

function inverseComparisonOperator(operator: string | undefined) {
  switch (operator) {
    case ">": return "<=";
    case ">=": return "<";
    case "<": return ">=";
    case "<=": return ">";
    case "==": return "!=";
    case "!=": return "==";
    default: return undefined;
  }
}

function numericValue(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

