const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { spawn, spawnSync } = require("node:child_process");

const player = process.env.STM_PLAYER_BIN;
const projector = process.env.STM_PROJECTOR_BIN;
const first = 1609459200;

function fixture(root) {
  const source = path.join(root, "source");
  const eventDir = path.join(source, "event-journal", "20210101");
  const metricsDir = path.join(source, "metrics-journal", "20210101");
  fs.mkdirSync(eventDir, { recursive: true });
  fs.mkdirSync(metricsDir, { recursive: true });
  const producer = { component: "stm", run_id: "fixture-run", started_at: first };
  const event = (seq, time, type, sourceFields = {}) => ({
    schema_version: 2, record_type: "event", capture_id: "fixture-run", run_id: "fixture-run",
    producer, record_id: `fixture-run:event:${seq}`, seq, time, event_time: time,
    emitted_at: time + 0.1, type, source: sourceFields
  });
  const entries = [event(0, first, "run_started"), { ...event(1, first + 1, "flow_detected", {
    stream_key: "stream-a", flow_key: "flow-a", proto: "RTP"
  }), detail: { last_error_time: first, time: 4026531840 } }];
  fs.writeFileSync(path.join(eventDir, "00.ndjson"), entries.map((item) => JSON.stringify(item)).join("\n") + "\n");
  fs.writeFileSync(path.join(metricsDir, "00.ndjson"), JSON.stringify({
    schema_version: 2, record_type: "metrics_snapshot", capture_id: "fixture-run", run_id: "fixture-run",
    producer, record_id: "fixture-run:metrics:0", seq: 0, time: first + 2,
    emitted_at: first + 2.1, metrics: [], interfaces: []
  }) + "\n");
  return source;
}

function records(root, kind) {
  const directory = path.join(root, kind);
  const result = [];
  const walk = (current) => {
    if (!fs.existsSync(current)) return;
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      const candidate = path.join(current, entry.name);
      if (entry.isDirectory()) walk(candidate);
      else if (entry.name.endsWith(".ndjson")) result.push(...fs.readFileSync(candidate, "utf8").trim().split("\n").map(JSON.parse));
    }
  };
  walk(directory);
  return result;
}

function run(binary, args) {
  const result = spawnSync(binary, args, { encoding: "utf8", timeout: 10000 });
  assert.equal(result.status, 0, result.stderr || result.stdout);
  return result.stdout;
}

test("stm_player preserves original timestamps and projects the same journal", { skip: !player || !projector }, () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-player-original-"));
  try {
    const source = fixture(root);
    const output = path.join(root, "output");
    run(player, [`--source=${source}`, `--output=${output}`, "--time-mode=original", "--speed=1000"]);
    const events = records(output, "event-journal");
    const metrics = records(output, "metrics-journal");
    assert.deepEqual(events.map((item) => item.time), [first, first + 1]);
    assert.equal(metrics[0].time, first + 2);
    assert.equal(events[1].record_id, "fixture-run:event:1");
    assert.equal(JSON.parse(fs.readFileSync(path.join(output, "player-state.json"))).state, "finished");
    const projected = path.join(output, "derived");
    run(projector, [`--event-journal-dir=${path.join(output, "event-journal")}`,
      `--metrics-journal-dir=${path.join(output, "metrics-journal")}`, `--output-dir=${projected}`,
      "--retention-hours=0", "--once"]);
    assert.equal(records(projected, "timeline/availability").length, 1);
    assert.ok(records(projected, "streams/delta").length >= 1);
  } finally { fs.rmSync(root, { recursive: true, force: true }); }
});

test("stm_player shifts timestamps to wall time and refuses an occupied output", { skip: !player }, () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-player-current-"));
  try {
    const source = fixture(root);
    const output = path.join(root, "output");
    const started = Date.now() / 1000;
    run(player, [`--source=${source}`, `--output=${output}`, "--time-mode=current", "--speed=1000"]);
    const events = records(output, "event-journal");
    const metrics = records(output, "metrics-journal");
    assert.ok(events[0].time >= started && events[0].time <= Date.now() / 1000);
    assert.ok(Math.abs(events[1].time - events[0].time - 0.001) < 0.0001);
    assert.ok(Math.abs(metrics[0].time - events[0].time - 0.002) < 0.0001);
    assert.equal(events[0].producer.started_at, events[0].time);
    assert.equal(events[1].detail.last_error_time, events[0].time);
    assert.equal(events[1].detail.time, 4026531840);
    assert.equal(events[1].record_id, "fixture-run:event:1");
    const repeated = spawnSync(player, [`--source=${source}`, `--output=${output}`], { encoding: "utf8" });
    assert.notEqual(repeated.status, 0);
    assert.match(repeated.stderr, /must be empty/);
  } finally { fs.rmSync(root, { recursive: true, force: true }); }
});

test("stm_player can start paused and resume through its control socket", { skip: !player }, async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-player-pause-"));
  const source = fixture(root);
  const output = path.join(root, "output");
  const child = spawn(player, [`--source=${source}`, `--output=${output}`, "--time-mode=original", "--speed=1000", "--start-paused"]);
  try {
    for (let i = 0; i < 100 && !fs.existsSync(path.join(output, "player.sock")); i += 1) {
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
    assert.ok(fs.existsSync(path.join(output, "player.sock")));
    const status = JSON.parse(run(player, [`--output=${output}`, "--command=status"]));
    assert.equal(status.state, "paused");
    assert.equal(status.current_time, first);
    run(player, [`--output=${output}`, "--command=resume"]);
    await new Promise((resolve, reject) => {
      if (child.exitCode !== null) return child.exitCode === 0 ? resolve() : reject(new Error(`player exited ${child.exitCode}`));
      child.once("error", reject);
      child.once("exit", (code) => code === 0 ? resolve() : reject(new Error(`player exited ${code}`)));
    });
    assert.equal(records(output, "event-journal").length, 2);
  } finally {
    if (child.exitCode === null) child.kill("SIGTERM");
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("current mode starts its wall-time mapping when start-paused playback resumes", { skip: !player }, async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-player-start-anchor-"));
  const source = fixture(root);
  const output = path.join(root, "output");
  const child = spawn(player, [`--source=${source}`, `--output=${output}`, "--time-mode=current", "--speed=1000", "--start-paused"]);
  try {
    for (let i = 0; i < 100 && !fs.existsSync(path.join(output, "player.sock")); i += 1) {
