void stream_state_projector::write_delta(const json &event, const char *action) {
	json delta{
		{"schema_version", 2},
		{"record_type", "stream_state_delta"},
		{"time", event.value("event_time", event.value("time", 0.0))},
		{"action", action},
		{"source_record_id", event.value("record_id", std::string{})},
		{"event", event},
	};
	m_delta_writer->dump_at(delta["time"].get<double>(), delta);
}

void stream_state_projector::checkpoint_if_needed(double time) {
	const auto minute = static_cast<std::int64_t>(std::floor(time / 60.0));
	if(m_last_checkpoint_minute == minute) return;
	write_checkpoint(time);
	m_last_checkpoint_minute = minute;
}

void stream_state_projector::write_checkpoint(double time) const {
	const auto path = checkpoint_path(m_cfg.root_dir, time);
	std::filesystem::create_directories(path.parent_path());
	const auto temporary = path.string() + ".tmp";
	std::ofstream output(temporary, std::ios::trunc);
	if(!output) return;
	json checkpoint = export_state();
	checkpoint["schema_version"] = 2;
	checkpoint["record_type"] = "stream_state_checkpoint";
	checkpoint["time"] = time;
	output << checkpoint.dump() << '\n';
	output.flush();
	std::error_code ec{};
	std::filesystem::rename(temporary, path, ec);
	if(ec) {
		std::filesystem::remove(path, ec);

