import type { EventLogItem } from "../types/api";

export type EventRelation = {
  counterpartTypes: string[];
  direction: "before" | "after";
  boundaryTypes?: string[];
};

export type EventRelationEndpoint = {
  phase: "start" | "end";
  style: "occurred" | "recovered" | "detected" | "flow-recovered" | "lost";
  label: string;
  symbol: string;
};

export type EventRelationPair = {
  start: EventLogItem;
  end: EventLogItem;
  duration: number;
  lifecycle: boolean;
};

export function eventRelationEndpoint(event: EventLogItem): EventRelationEndpoint | null {
  if (event.type === "flow_detected") return { phase: "start", style: "detected", label: "Detected", symbol: "●" };
  if (event.type === "flow_recovered") return { phase: "start", style: "flow-recovered", label: "Recovered", symbol: "●" };
  if (event.type === "flow_lost") return { phase: "end", style: "lost", label: "Lost", symbol: "■" };
  if (event.type === "alert_detected" || event.type === "alert_data_unavailable" || event.type.endsWith("_occurred")) {
    return { phase: "start", style: "occurred", label: "Occurred", symbol: "●" };
  }
  if (event.type === "alert_recovered" || event.type === "alert_data_available" || event.type.endsWith("_recovered")) {
    return { phase: "end", style: "recovered", label: "Recovered", symbol: "✓" };
  }
  return null;
}

export function eventRelationPairFor(source: EventLogItem | null, related: EventLogItem | null): EventRelationPair | null {
  if (!source || !related || !sameRelationTarget(source, related)) return null;
  const relation = eventRelationFor(source);
  const sourceEndpoint = eventRelationEndpoint(source);
  const relatedEndpoint = eventRelationEndpoint(related);
  if (!relation?.counterpartTypes.includes(related.type) || !sourceEndpoint || !relatedEndpoint || sourceEndpoint.phase === relatedEndpoint.phase) return null;
  const start = sourceEndpoint.phase === "start" ? source : related;
  const end = sourceEndpoint.phase === "end" ? source : related;
  if (end.time <= start.time) return null;
  const lifecycle = start.type === "flow_detected" || start.type === "flow_recovered";
  if (lifecycle && (!start.flowKey || !end.flowKey)) return null;
  return { start, end, duration: end.time - start.time, lifecycle };
}

export function relationPairTooltip(pair: EventRelationPair, duration: string) {
  const interval = `${eventRelationEndpoint(pair.start)?.label} → ${eventRelationEndpoint(pair.end)?.label} · ${duration}`;
  return pair.lifecycle ? `${interval}\nEvent interval: may include loss detection delay; not last-packet lifetime.` : interval;
}

export function eventRelationFor(event: EventLogItem): EventRelation | null {
  if (event.type === "alert_detected") return { counterpartTypes: ["alert_recovered"], direction: "after" };
  if (event.type === "alert_recovered") return { counterpartTypes: ["alert_detected"], direction: "before" };
  if (event.type === "alert_data_unavailable") return { counterpartTypes: ["alert_data_available"], direction: "after" };
  if (event.type === "alert_data_available") return { counterpartTypes: ["alert_data_unavailable"], direction: "before" };
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    const boundaryTypes = subject === "flow" ? ["flow_detected", "flow_recovered", "flow_lost"] : undefined;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before", boundaryTypes };
    return { counterpartTypes: [`${subject}_lost`], direction: "after", boundaryTypes };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}

export function findRelatedEvent(events: EventLogItem[], source: EventLogItem, relation: EventRelation) {
  if (relation.boundaryTypes && !source.flowKey) return null;
  // For a flow, the next lifecycle transition must be its counterpart. Do not
  // skip an intervening Detect/Recovered/Lost just because it is not a match.
  const types = relation.boundaryTypes ?? relation.counterpartTypes;
  const nearest = events.reduce<EventLogItem | null>((closest, candidate) => {
    if (candidate.id === source.id || !types.includes(candidate.type) || !sameRelationTarget(source, candidate)) return closest;
    if (relation.direction === "before" ? candidate.time >= source.time : candidate.time <= source.time) return closest;
    if (!closest || Math.abs(candidate.time - source.time) < Math.abs(closest.time - source.time)) return candidate;
    // Conflicting simultaneous transitions are ambiguous; prefer the blocker.
    if (candidate.time === closest.time && !relation.counterpartTypes.includes(candidate.type)) return candidate;
    return closest;
  }, null);
  return nearest && relation.counterpartTypes.includes(nearest.type) ? nearest : null;
}

function alertStateKey(event: EventLogItem) {
  const detail = event.detail;
  if (!detail || typeof detail !== "object" || Array.isArray(detail)) return null;
  const key = (detail as Record<string, unknown>).state_key;
  return typeof key === "string" && key ? key : null;
}

function sameRelationTarget(source: EventLogItem, candidate: EventLogItem) {
  const sourceStateKey = alertStateKey(source);
  const candidateStateKey = alertStateKey(candidate);
  if (sourceStateKey || candidateStateKey) return Boolean(sourceStateKey && sourceStateKey === candidateStateKey);
  if (source.flowKey || candidate.flowKey) return Boolean(source.flowKey && source.flowKey === candidate.flowKey);
  return Boolean(source.streamKey && source.streamKey === candidate.streamKey);
}
