// node --test fe/tests/events-relations.test.cjs
const { test } = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const vm = require('node:vm');
const esbuild = require('../server/node_modules/esbuild');
const output = esbuild.buildSync({ entryPoints:[path.join(__dirname,'../client/src/components/eventRelations.ts')],
  bundle:true,write:false,platform:'node',format:'cjs' }).outputFiles[0].text;
const exportsContainer = { exports:{} };
vm.runInNewContext(output,{module:exportsContainer,exports:exportsContainer.exports});
const { eventRelationFor, eventRelationEndpoint, eventRelationPairFor, findRelatedEvent, relationPairTooltip } = exportsContainer.exports;
const event = (id,type,time,overrides={}) => ({id,type,time,flowKey:'flow',streamKey:'stream',scope:'flow',level:'info',message:type,...overrides});
const detect = event('detect','flow_detected',10);
const lost = event('lost','flow_lost',20);
const recovered = event('recovered','flow_recovered',30);
const lost2 = event('lost-2','flow_lost',40);
const related = (events,source) => findRelatedEvent(events,source,eventRelationFor(source));

test('Flow Detect/Lost and Recovered/Lost pair in either selection direction',()=>{
  const events=[lost2,detect,recovered,lost];
  for(const [source,expected] of [[detect,lost],[lost,detect],[recovered,lost2],[lost2,recovered]]) {
    assert.equal(related(events,source)?.id,expected.id);
    const pair=eventRelationPairFor(source,expected);
    assert.equal(pair.start.time,pair.end.time-10);
    assert.equal(pair.duration,10);assert.equal(pair.lifecycle,true);
    assert.match(relationPairTooltip(pair,'10.000 s'),/→ Lost · 10.000 s/);
    assert.match(relationPairTooltip(pair,'10.000 s'),/loss detection delay/);
  }
  assert.equal(eventRelationEndpoint(lost).symbol,'■');
  assert.equal(eventRelationEndpoint(lost).style,'lost');
  assert.equal(eventRelationEndpoint(recovered).phase,'start');
  assert.equal(eventRelationEndpoint(recovered).symbol,'●');
});

test('Flow pairs do not cross a new Detect/Recovered or an unmatched Lost',()=>{
  assert.equal(related([detect,recovered,lost2],detect),null);
  assert.equal(related([detect,event('redetect','flow_detected',15),lost],detect),null);
  assert.equal(related([detect,lost,lost2],lost2),null);
  assert.equal(related([detect,lost,lost2],lost)?.id,detect.id);
  assert.equal(related([detect,recovered,lost2],lost2)?.id,recovered.id);
  const simultaneous = event('redetect','flow_detected',20);
  assert.equal(related([detect,lost,simultaneous],detect),null);
  assert.equal(related([simultaneous,lost,detect],detect),null);
});

test('Flow pairing requires the same flow key, not a matching stream or display label',()=>{
  const other=event('other','flow_detected',15,{flowKey:'other'});
  assert.equal(related([detect,other,lost],detect)?.id,lost.id);
  assert.equal(related([event('other-lost','flow_lost',12,{flowKey:'other'}),lost],detect)?.id,lost.id);
  assert.equal(eventRelationPairFor(detect,event('other-lost','flow_lost',20,{flowKey:'other'})),null);
  const noKey={...detect,flowKey:undefined};
  assert.equal(related([noKey,{...lost,flowKey:undefined}],noKey),null);
  assert.equal(eventRelationPairFor(noKey,{...lost,flowKey:undefined}),null);
});

test('Missing counterparts, reversed time, and non-counterpart event types remain neutral',()=>{
  assert.equal(related([detect],detect),null);
  assert.equal(related([lost],lost),null);
  assert.equal(eventRelationPairFor(detect,null),null);
  assert.equal(eventRelationPairFor(detect,event('old-lost','flow_lost',5)),null);
  assert.equal(eventRelationPairFor(detect,recovered),null);
  assert.equal(eventRelationPairFor(detect,event('incident','packet_loss_recovered',20)),null);
  assert.equal(related([detect,event('same-time','flow_lost',10)],detect),null);
});

test('Incident pairs preserve check marks and alert rule state-key matching',()=>{
  const start=event('alert','alert_detected',10,{detail:{state_key:'rule-a'}});
  const end=event('alert-end','alert_recovered',20,{detail:{state_key:'rule-a'}});
  const wrong=event('wrong-rule','alert_recovered',15,{detail:{state_key:'rule-b'}});
  assert.equal(related([start,wrong,end],start)?.id,end.id);
  const pair=eventRelationPairFor(start,end);
  assert.equal(pair.lifecycle,false);
  assert.equal(relationPairTooltip(pair,'10.000 s'),'Occurred → Recovered · 10.000 s');
  assert.equal(eventRelationEndpoint(end).symbol,'✓');
  assert.equal(eventRelationPairFor(start,wrong),null);
  for(const prefix of ['packet_loss','flow_error']) {
    const incident=event('start',prefix+'_occurred',10);
    const recovery=event('end',prefix+'_recovered',20);
    assert.equal(related([incident,recovery],incident)?.id,recovery.id);
    assert.equal(eventRelationPairFor(incident,recovery).lifecycle,false);
  }
});
