    awk -v value="$1" 'BEGIN { if (value !~ /^[0-9]+([.][0-9]+)?$/ || value + 0 <= 0) exit 1 }'
}

safe_path "$output_dir" || { echo "output must be an absolute path without spaces or special characters" >&2; exit 2; }
output_dir=$(realpath -m -- "$output_dir")
runtime_dir=${STM_REPLAY_RUNTIME_DIR:-"$output_dir.supervisor"}
state_dir=${STM_REPLAY_STATE_DIR:-"$output_dir.fe-state"}
safe_path "$runtime_dir" || { echo "invalid supervisor runtime directory" >&2; exit 2; }
safe_path "$state_dir" || { echo "invalid FE state directory" >&2; exit 2; }
runtime_dir=$(realpath -m -- "$runtime_dir")
state_dir=$(realpath -m -- "$state_dir")

case "$output_dir" in /tmp/stm|/tmp/stm/*) echo "refusing to use production /tmp/stm" >&2; exit 2 ;; esac
for separate_dir in "$runtime_dir" "$state_dir"; do
    case "$separate_dir" in
        "$output_dir"|"$output_dir"/*) echo "runtime and FE state must be outside the replay output" >&2; exit 2 ;;
    esac
    case "$output_dir" in
        "$separate_dir"|"$separate_dir"/*) echo "replay output must be separate from runtime and FE state" >&2; exit 2 ;;
    esac
done
case "$runtime_dir" in "$state_dir"|"$state_dir"/*) echo "runtime and FE state must be separate" >&2; exit 2 ;; esac
case "$state_dir" in "$runtime_dir"/*) echo "runtime and FE state must be separate" >&2; exit 2 ;; esac
[ "${#output_dir}" -le 90 ] && [ "${#runtime_dir}" -le 85 ] || {
    echo "output or runtime path is too long for a Unix control socket" >&2; exit 2;
}

STM_BIN_DIR=${STM_BIN_DIR:-"$project_root/be/build"}
STM_CONFIG_DIR=${STM_CONFIG_DIR:-"$project_root/conf"}
STM_FE_DIR=${STM_FE_DIR:-"$project_root/fe"}
STM_NODE_BIN=${STM_NODE_BIN:-$(command -v node || true)}
for dependency_path in "$STM_BIN_DIR" "$STM_CONFIG_DIR" "$STM_FE_DIR" "$STM_NODE_BIN"; do
    safe_path "$dependency_path" || { echo "dependency paths must be absolute without spaces or special characters" >&2; exit 2; }
done

if [ "$action" = up ]; then
    [ -n "$source_dir" ] || { echo "--source is required for up" >&2; exit 2; }
    safe_path "$source_dir" || { echo "source must be an absolute path without spaces or special characters" >&2; exit 2; }
    source_dir=$(realpath -- "$source_dir")
    [ -d "$source_dir/event-journal" ] && [ -d "$source_dir/metrics-journal" ] || {
        echo "source needs event-journal and metrics-journal directories" >&2; exit 2;
    }
    case "$output_dir" in "$source_dir"|"$source_dir"/*) echo "source and output must be separate" >&2; exit 2 ;; esac
    case "$source_dir" in "$output_dir"/*) echo "source and output must be separate" >&2; exit 2 ;; esac
    for separate_dir in "$runtime_dir" "$state_dir"; do
        case "$separate_dir" in "$source_dir"|"$source_dir"/*) echo "runtime and FE state must be outside the source" >&2; exit 2 ;; esac
    done
    if [ -e "$output_dir" ] && [ -n "$(find "$output_dir" -mindepth 1 -maxdepth 1 -print -quit)" ]; then
        echo "replay output must be empty: $output_dir" >&2
        exit 2
    fi
    case "$time_mode" in current|original) ;; *) echo "time mode must be current or original" >&2; exit 2 ;; esac
    case "$loop_enabled" in 0|1) ;; *) echo "STM_REPLAY_LOOP must be 0 or 1" >&2; exit 2 ;; esac
    if [ "$loop_enabled" = 1 ] && [ "$time_mode" != current ]; then
        echo "loop playback requires current time mode" >&2
        exit 2
    fi
    safe_number "$speed" && safe_number "$loop_gap" || {
        echo "speed and loop gap must be positive decimal numbers" >&2; exit 2;
    }
    case "$fe_host" in *[!A-Za-z0-9._:-]*|'') echo "invalid FE host" >&2; exit 2 ;; esac
    case "$fe_port" in *[!0-9]*|'') echo "invalid FE port" >&2; exit 2 ;; esac
    [ "$fe_port" -ge 1 ] && [ "$fe_port" -le 65535 ] || { echo "FE port must be 1..65535" >&2; exit 2; }
    [ -x "$STM_BIN_DIR/stm_player" ] && [ -x "$STM_BIN_DIR/stm_projector" ] && [ -f "$STM_FE_DIR/server/dist/index.js" ] && [ -x "$STM_NODE_BIN" ] || {
        echo "build stm_player, stm_projector and FE server before up" >&2; exit 2;
    }
    [ -f "$STM_CONFIG_DIR/stm_config.json" ] && [ -f "$STM_CONFIG_DIR/capture_policy.json" ] || {
        echo "configuration files are missing from STM_CONFIG_DIR" >&2; exit 2;
    }
else
    source_dir=${source_dir:-/nonexistent}
fi

STM_REPLAY_SOURCE_DIR=$source_dir
STM_REPLAY_OUTPUT_DIR=$output_dir
STM_REPLAY_RUNTIME_DIR=$runtime_dir
STM_REPLAY_STATE_DIR=$state_dir
STM_REPLAY_TIME_MODE=$time_mode
STM_REPLAY_SPEED=$speed
STM_REPLAY_LOOP_GAP=$loop_gap
STM_REPLAY_HOST=$fe_host
STM_REPLAY_PORT=$fe_port
STM_REPLAY_LOOP_FLAG=
[ "$loop_enabled" = 1 ] && STM_REPLAY_LOOP_FLAG=--loop
export STM_BIN_DIR STM_CONFIG_DIR STM_FE_DIR STM_NODE_BIN STM_REPLAY_SOURCE_DIR
export STM_REPLAY_OUTPUT_DIR STM_REPLAY_RUNTIME_DIR STM_REPLAY_STATE_DIR
export STM_REPLAY_TIME_MODE STM_REPLAY_SPEED STM_REPLAY_LOOP_GAP STM_REPLAY_LOOP_FLAG
export STM_REPLAY_HOST STM_REPLAY_PORT

supervisor_running() {
    supervisorctl -c "$supervisor_config" pid >/dev/null 2>&1
}

if [ "$action" = up ]; then
    command -v supervisord >/dev/null && command -v supervisorctl >/dev/null || {
        echo "supervisord and supervisorctl are required" >&2; exit 1;
    }
    if supervisor_running; then
        echo "a replay supervisor already uses $runtime_dir; use status or shutdown" >&2
        exit 1
    fi
    mkdir -p "$runtime_dir" "$state_dir"
    supervisord -c "$supervisor_config"
    attempt=0
    until supervisor_running; do
        attempt=$((attempt + 1))
        [ "$attempt" -lt 50 ] || { echo "replay supervisor did not become ready" >&2; exit 1; }
        sleep 0.1
    done
    for program in player projector frontend; do
        if ! supervisorctl -c "$supervisor_config" start "$program"; then
            supervisorctl -c "$supervisor_config" shutdown || true
            echo "failed to start $program; use a new empty output for the next attempt" >&2
            exit 1
        fi
    done
    echo "replay services are ready and player is paused; run resume with the same --output" >&2
    exit 0
fi

if ! supervisor_running; then
    if [ "$action" = status ] || [ "$action" = shutdown ]; then
        echo "replay supervisord is not running" >&2
        exit 0
    fi
    echo "replay supervisord is not running" >&2
    exit 1
fi

case "$action" in
    status) exec supervisorctl -c "$supervisor_config" status ;;
    shutdown) exec supervisorctl -c "$supervisor_config" shutdown ;;
    pause|resume|stop) exec "$STM_BIN_DIR/stm_player" "--output=$output_dir" "--command=$action" ;;
esac

