const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { spawnSync } = require("node:child_process");

const root = path.resolve(__dirname, "../..");
const wrapper = path.join(root, "scripts/stm-player-supervisor");
const config = fs.readFileSync(path.join(root, "docker/supervisord.player.conf"), "utf8");

function fixture() {
  const work = fs.mkdtempSync(path.join(os.tmpdir(), "stm-player-supervisor-"));
  const source = path.join(work, "source");
  const output = path.join(work, "replay");
  const fakeBin = path.join(work, "fake-bin");
  const beBin = path.join(work, "be-bin");
  const feDir = path.join(work, "fe");
  const configDir = path.join(work, "conf");
  for (const dir of [path.join(source, "event-journal"), path.join(source, "metrics-journal"),
    fakeBin, beBin, path.join(feDir, "server/dist"), configDir]) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(configDir, "stm_config.json"), "{}\n");
  fs.writeFileSync(path.join(configDir, "capture_policy.json"), "{}\n");
  fs.writeFileSync(path.join(feDir, "server/dist/index.js"), "\n");
  fs.writeFileSync(path.join(fakeBin, "supervisord"),
    "#!/bin/sh\nset -eu\nprintf 'daemon:%s:%s\\n' \"$STM_REPLAY_LOOP_FLAG\" \"$STM_REPLAY_LOOP_GAP\" >> \"$STM_REPLAY_RUNTIME_DIR/trace\"\n: > \"$STM_REPLAY_RUNTIME_DIR/mock-running\"\n",
    { mode: 0o755 });
  fs.writeFileSync(path.join(fakeBin, "supervisorctl"),
    "#!/bin/sh\nset -eu\ncase \"$3\" in\n" +
    "  pid) test -f \"$STM_REPLAY_RUNTIME_DIR/mock-running\" ;;\n" +
    "  start) printf 'start:%s\\n' \"$4\" >> \"$STM_REPLAY_RUNTIME_DIR/trace\" ;;\n" +
    "  status) printf 'status\\n' >> \"$STM_REPLAY_RUNTIME_DIR/trace\" ;;\n" +
    "  shutdown) printf 'shutdown\\n' >> \"$STM_REPLAY_RUNTIME_DIR/trace\"; rm \"$STM_REPLAY_RUNTIME_DIR/mock-running\" ;;\n" +
    "esac\n",
    { mode: 0o755 });
  fs.writeFileSync(path.join(beBin, "stm_player"),
    "#!/bin/sh\nset -eu\nprintf 'player:%s:%s\\n' \"$1\" \"$2\" >> \"$STM_REPLAY_RUNTIME_DIR/trace\"\n",
    { mode: 0o755 });
  fs.writeFileSync(path.join(beBin, "stm_projector"), "#!/bin/sh\nexit 0\n", { mode: 0o755 });
  const env = { ...process.env, PATH: `${fakeBin}:${process.env.PATH}`,
    STM_BIN_DIR: beBin, STM_FE_DIR: feDir, STM_CONFIG_DIR: configDir, STM_NODE_BIN: process.execPath };
  return { work, source, output, env, runtime: `${output}.supervisor` };
}

function invoke(args, env) {
  return spawnSync(wrapper, args, { encoding: "utf8", env, timeout: 10000 });
}

test("dedicated supervisor config only starts the isolated replay pipeline", () => {
  assert.match(config, /\[program:player\]/);
  assert.match(config, /\[program:projector\]/);
  assert.match(config, /\[program:frontend\]/);
  assert.doesNotMatch(config, /\[program:(capture|stm|healthd|process-control)\]/);
  assert.match(config, /--start-paused/);
  assert.match(config, /--retention-hours=0/);
  assert.match(config, /--log-dir=%\(ENV_STM_REPLAY_OUTPUT_DIR\)s/);
  assert.match(config, /--state-dir=%\(ENV_STM_REPLAY_STATE_DIR\)s/);
  assert.match(config, /--playback-state-file=%\(ENV_STM_REPLAY_OUTPUT_DIR\)s\/player-state\.json/);
  assert.match(config, /file=%\(ENV_STM_REPLAY_RUNTIME_DIR\)s\/supervisor\.sock/);
});

test("wrapper starts player, projector and FE in order and controls the player", () => {
  const { work, source, output, runtime, env } = fixture();
  try {
    const up = invoke(["--source", source, "--output", output, "--loop", "--loop-gap", "0.5", "up"], env);
    assert.equal(up.status, 0, up.stderr);
    assert.deepEqual(fs.readFileSync(path.join(runtime, "trace"), "utf8").trim().split("\n"),
      ["daemon:--loop:0.5", "start:player", "start:projector", "start:frontend"]);
    assert.equal(invoke(["--output", output, "resume"], env).status, 0);
    assert.equal(invoke(["--output", output, "pause"], env).status, 0);
    assert.equal(invoke(["--output", output, "status"], env).status, 0);
    assert.equal(invoke(["--output", output, "shutdown"], env).status, 0);
    assert.match(fs.readFileSync(path.join(runtime, "trace"), "utf8"),
      /player:--output=.*replay:--command=resume\nplayer:--output=.*replay:--command=pause\nstatus\nshutdown\n$/);
  } finally { fs.rmSync(work, { recursive: true, force: true }); }
});

test("wrapper refuses an incompatible or reused output before starting a supervisor", () => {
  const { work, source, output, env } = fixture();
  try {
    const originalLoop = invoke(["--source", source, "--output", output, "--time-mode", "original", "--loop", "up"], env);
    assert.notEqual(originalLoop.status, 0);
    assert.match(originalLoop.stderr, /requires current/);
    fs.mkdirSync(output);
    fs.writeFileSync(path.join(output, "existing.ndjson"), "fixture\n");
    const reused = invoke(["--source", source, "--output", output, "up"], env);
    assert.notEqual(reused.status, 0);
    assert.match(reused.stderr, /must be empty/);
    assert.equal(fs.existsSync(`${output}.supervisor/mock-running`), false);
  } finally { fs.rmSync(work, { recursive: true, force: true }); }
});

