#!/bin/sh
set -eu

script_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
project_root=$(CDPATH= cd -- "$script_dir/.." && pwd)
supervisor_config="$project_root/docker/supervisord.player.conf"

usage() {
    cat <<'EOF'
Usage: scripts/stm-player-supervisor --output DIR [options] up|status|pause|resume|stop|shutdown

  up        Start an isolated supervisord with player paused, then projector and FE.
  status    Show the three supervised processes.
  pause     Pause the running player.
  resume    Start or resume playback after the other processes are ready.
  stop      Stop playback; projector and FE remain available.
  shutdown  Stop all three processes and the dedicated supervisord.

Options for up:
  --source DIR          Immutable directory containing event-journal and metrics-journal.
  --time-mode MODE      current (default) or original.
  --speed NUMBER        Positive playback speed (default: 1).
  --loop                Repeat continuously (current mode only).
  --loop-gap SECONDS    Positive wall-time gap between cycles (default: 1).
  --host HOST           FE bind host (default: 127.0.0.1).
  --port PORT           FE port (default: 3100).

Environment overrides: STM_BIN_DIR, STM_CONFIG_DIR, STM_FE_DIR, STM_NODE_BIN,
STM_REPLAY_SOURCE_DIR, STM_REPLAY_OUTPUT_DIR, STM_REPLAY_RUNTIME_DIR,
STM_REPLAY_STATE_DIR, STM_REPLAY_TIME_MODE, STM_REPLAY_SPEED,
STM_REPLAY_LOOP, STM_REPLAY_LOOP_GAP, STM_REPLAY_HOST, STM_REPLAY_PORT.
Each run needs a new empty output directory. The supervisor socket, logs and
FE state use separate sibling directories by default.
EOF
}

source_dir=${STM_REPLAY_SOURCE_DIR:-}
output_dir=${STM_REPLAY_OUTPUT_DIR:-}
time_mode=${STM_REPLAY_TIME_MODE:-current}
speed=${STM_REPLAY_SPEED:-1}
loop_enabled=${STM_REPLAY_LOOP:-0}
loop_gap=${STM_REPLAY_LOOP_GAP:-1}
fe_host=${STM_REPLAY_HOST:-127.0.0.1}
fe_port=${STM_REPLAY_PORT:-3100}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --source|--output|--time-mode|--speed|--loop-gap|--host|--port)
            [ "$#" -ge 2 ] || { echo "missing value for $1" >&2; exit 2; }
            case "$1" in
                --source) source_dir=$2 ;;
                --output) output_dir=$2 ;;
