const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const Module = require("node:module");
const esbuild = require("../server/node_modules/esbuild");

const source = path.resolve(__dirname, "../client/src/playbackClock.ts");
const compiled = esbuild.transformSync(fs.readFileSync(source, "utf8"), { loader: "ts", format: "cjs" });
const clockModule = new Module(source);
clockModule.filename = source;
clockModule.paths = Module._nodeModulePaths(path.dirname(source));
clockModule._compile(compiled.code, source);
const { dataNowSec, setPlaybackStatus } = clockModule.exports;

test("recorded playback clock advances at selected speed and freezes when paused", () => {
  const base = { enabled: true, mode: "original", speed: 2, sourceFirst: 1609459200,
    sourceLast: 1609459300, now: 1609459205, state: "playing" };
  try {
    setPlaybackStatus(base);
    assert.ok(dataNowSec() >= base.now && dataNowSec() < base.now + 1);
    setPlaybackStatus({ ...base, state: "paused", now: base.now + 3 });
    assert.equal(dataNowSec(), base.now + 3);
    setPlaybackStatus({ ...base, mode: "current" });
    assert.ok(Math.abs(dataNowSec() - Date.now() / 1000) < 1);
  } finally { setPlaybackStatus(null); }
});
