  const query = new URLSearchParams({ time: String(timeSec) });
  if (options?.eventRange) {
    query.set("overviewEventFrom", String(options.eventRange.from));
    query.set("overviewEventTo", String(options.eventRange.to));
  }
  if (options?.includeSparkline) query.set("includeSparkline", "1");
  return getJson("/api/streams?" + query.toString());
}

