async function createProjectedTails(app: FastifyInstance, store: StreamStore, sockets: SocketServer, captureHealth: CaptureHealthStore): Promise<{ tails: RunningTail[]; flushMetrics: () => void }> {
  const state = await loadProjectedStreamState(config.streamStateDir, Number.POSITIVE_INFINITY);
  const applyStreams = (time: number, dropPreviousRun = false) => store.applyStreamSnapshot(materializeProjectedStreamStates(state.streams, time), time, dropPreviousRun);
  if (state.hasRecords) applyStreams(dataNowSec());

  const streams = new RotatingNdjsonTail({ root: `${config.streamStateDir}/delta`, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    recordId: sourceRecordId,
    initialSkipRecordIds: state.latestDeltaRecordIds,
    onLine: (line) => { try { const delta = parseRecord(line); const time = Number(delta?.time ?? 0); if (!delta || !Number.isFinite(time) || time < state.checkpointTime) return; const runChanged = applyProjectedLifecycleEvent(state.streams, delta.event, state.run); applyStreams(time, runChanged); } catch (error) { app.log.warn({ error }, "failed to parse projected stream delta"); } },
  }

  addTimelineEvent(input: NormalizedTimelineInput) {
    this.tick(input.time);
    this.latestTimelineTime = Math.max(this.latestTimelineTime ?? input.time, input.time);
    if (input.kind === "stream_reclassified" || input.kind === "flow_reclassified") {
      const timelineKey = input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
      this.timeline.delete(timelineKey);
      this.emit("timeline:update");
      return;
    }
    const row = this.ensureTimelineRow(input);
    row.firstSeen = Math.min(row.firstSeen, input.time);
    row.lastSeen = Math.max(row.lastSeen, input.time);

    if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
      row.active = true;
      const current = row.segments[row.segments.length - 1];
      if (!current || current.end !== null) {
        row.segments.push({ start: input.time, end: null });
      }
    } else if (input.kind === "stream_lost" || input.kind === "flow_lost") {
      row.active = false;
      const current = row.segments[row.segments.length - 1];
      if (current && current.end === null) {
        current.end = input.time;
      } else if (!current) {
        row.segments.push({ start: input.time, end: input.time });
      }
    }

    this.pruneTimeline(this.latestTimelineTime);
    this.enforceTimelineBudget();
    this.emit("timeline:update");
  }

  addMetric(input: NormalizedMetricInput) {
    this.addMetrics([input]);
  }

  addMetrics(inputs: NormalizedMetricInput[]) {
    const updatedStreams = new Set<string>();
    let latestTime = Number.NEGATIVE_INFINITY;
    for (const input of inputs) {
      this.tick(input.time);
      // Lifecycle projection owns identity and active/lost state. A historical
      // metric sample must not recreate a stream or flow that has been lost.
      const stream = this.streams.get(input.streamKey);
      if (!stream) continue;
      const flow = stream.flows.find((item) => item.flowKey === input.flowKey);
      if (!flow) continue;
      if (input.interfaceId !== undefined) {
        stream.interfaceId ??= input.interfaceId;
        flow.interfaceId ??= input.interfaceId;
        const interfaceName = this.interfaceById(input.interfaceId)?.name;
        if (interfaceName) {
          stream.interfaceName ??= interfaceName;
          flow.interfaceName ??= interfaceName;
        }
      }
      flow.metrics = input.metrics;
      flow.lastSeen = input.time;
      // Lifecycle records establish the flow identity but do not include its
      // monitoring-target classification. Metric samples are authoritative
      // for that classification, which is also used by the Inspector to
      // resolve target-specific Alert policy overrides.
      if (input.monitoringTargetIds?.length) flow.monitoringTargetIds = input.monitoringTargetIds;
      if (input.monitoringGroupIds?.length) {
        flow.monitoringGroupIds = input.monitoringGroupIds;
        stream.monitoringGroupIds = input.monitoringGroupIds;
      }

      const history = this.flowHistory.get(input.flowKey) ?? [];
      history.push({ time: input.time, metrics: input.metrics });
      const bitrate = input.metrics.bitrate?.value ?? input.metrics.bitrate?.avg ?? 0;
      const sparkline = this.flowSparklines.get(input.flowKey) ?? [];
      sparkline.push(bitrate);
      this.trimSparkline(sparkline);
      this.flowSparklines.set(input.flowKey, sparkline);
      this.prune(history, input.time);
      this.flowHistory.set(input.flowKey, history);
      this.recomputeStreamBitrate(stream, input.time);
      updatedStreams.add(input.streamKey);
      latestTime = Math.max(latestTime, input.time);
    }
    if (updatedStreams.size === 0) return;
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, latestTime);
    this.emit("streams:update");
    for (const streamKey of updatedStreams) this.emit("metrics:update", streamKey);
  }


  applyTopologySnapshot(snapshot: TopologySnapshot) {
    this.topology = this.topologyDisplay.apply(snapshot);
    this.emit("topology:update");
  }

  getTopology(): TopologySnapshot | undefined {
    if (!this.topology) return undefined;
    return {
      ...this.topology,
      nodes: this.topology.nodes.map((node) => ({ ...node })),
      edges: this.topology.edges.map((edge) => ({ ...edge }))
    };
  }

