    if (event.type !== "transport_reclassified") return;
    const detail = asRecord(event.detail);
    const from = asRecord(detail?.from);
    if (!from) return;
    let changed = false;
    for (const entry of recordArray(from.flows)) {
      const source = asRecord(entry.source);
      const streamKey = stringRecordValue(source?.stream_key);
      const flowKey = stringRecordValue(source?.flow_key);
      if (!streamKey || !flowKey) continue;
      changed = this.removeReclassifiedFlow(streamKey, flowKey) || changed;
    }
    for (const entry of recordArray(from.streams)) {
      const source = asRecord(entry.source);
      const streamKey = stringRecordValue(source?.stream_key);
      if (!streamKey) continue;
      changed = this.removeReclassifiedStream(streamKey) || changed;
    }
    if (changed) this.emit("streams:update");
  }

